:root {
  --ink: #02060e;
  --ink-2: #06101e;
  --cyan: #2ee7ff;
  --cyan-soft: #7ff4ff;
  --blue: #2d83ff;
  --orange: #ff7a1f;
  --orange-soft: #ffb35c;
  --pink: #ff3d81;
  --white: #edf9ff;
  --muted: #7893a8;
  --line: rgba(108, 203, 238, 0.18);
  --glass: rgba(5, 15, 27, 0.78);
  --panel: rgba(8, 22, 38, 0.72);
  --font-display: 'Orbitron', 'Arial Black', sans-serif;
  --font-ui: 'Rajdhani', 'Arial Narrow', sans-serif;
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
  --safe-t: env(safe-area-inset-top, 0px);
  --safe-b: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; }
html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--ink);
  color: var(--white);
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
}
body { overscroll-behavior: none; touch-action: none; }
#app { position: fixed; inset: 0; overflow: hidden; background: #02060e; }
#scene { position: absolute; inset: 0; width: 100%; height: 100%; display: block; outline: none; }
button { font: inherit; color: inherit; border: 0; background: none; cursor: pointer; }
button:focus-visible { outline: 2px solid var(--cyan); outline-offset: 3px; }
.hidden { display: none !important; }
.glass {
  background:
    linear-gradient(150deg, rgba(20, 47, 72, 0.42), rgba(3, 10, 19, 0.82) 55%),
    var(--glass);
  border: 1px solid rgba(112, 219, 255, 0.17);
  box-shadow:
    0 24px 60px rgba(0, 0, 0, 0.52),
    inset 0 1px 0 rgba(190, 244, 255, 0.12),
    inset 0 0 60px rgba(16, 90, 130, 0.08);
  backdrop-filter: blur(16px);
  -webkit-backdrop-filter: blur(16px);
}

/* ------- atmosphere ------- */
.vignette {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
  background:
    radial-gradient(ellipse at 50% 46%, transparent 38%, rgba(0, 3, 9, 0.34) 78%, rgba(0, 2, 6, 0.72) 100%),
    linear-gradient(180deg, rgba(0, 4, 10, 0.34), transparent 18%, transparent 76%, rgba(0, 3, 9, 0.45));
}
.scanlines {
  position: absolute; inset: 0; pointer-events: none; z-index: 3; opacity: 0.16;
  background: repeating-linear-gradient(180deg, transparent 0 3px, rgba(0, 10, 18, 0.18) 3px 4px);
  mix-blend-mode: multiply;
}
.eyebrow {
  font-family: var(--font-display);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.22em;
  color: var(--cyan);
  display: block;
}

/* ------- loader ------- */
.loader {
  position: absolute; inset: 0; z-index: 100;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 22px;
  background:
    radial-gradient(circle at 50% 44%, rgba(27, 105, 142, 0.22), transparent 38%),
    linear-gradient(180deg, #02060e, #030b16 60%, #02060d);
  transition: opacity 0.7s ease, visibility 0.7s;
}
.loader.done { opacity: 0; visibility: hidden; }
.loader-mark {
  width: 82px; height: 90px; position: relative; display: flex; align-items: center; justify-content: center;
  clip-path: polygon(50% 0, 100% 24%, 100% 76%, 50% 100%, 0 76%, 0 24%);
  background: linear-gradient(145deg, rgba(46, 231, 255, 0.22), rgba(46, 131, 255, 0.05));
  border: 1px solid rgba(46, 231, 255, 0.4);
  font-family: var(--font-display); font-size: 22px; font-weight: 900; letter-spacing: -0.12em;
  color: var(--cyan); text-shadow: 0 0 24px rgba(46, 231, 255, 0.9);
  animation: loaderPulse 2s ease-in-out infinite;
}
.loader-mark span:first-child { color: var(--white); }
@keyframes loaderPulse {
  0%, 100% { filter: drop-shadow(0 0 10px rgba(46, 231, 255, 0.45)); transform: scale(1); }
  50% { filter: drop-shadow(0 0 30px rgba(46, 231, 255, 0.8)); transform: scale(1.04); }
}
.loader-title {
  font-family: var(--font-display); font-weight: 900; letter-spacing: 0.24em; font-size: 20px;
  color: var(--white); text-shadow: 0 0 26px rgba(46, 231, 255, 0.35);
}
.loader-bar { width: 270px; height: 3px; background: rgba(120, 190, 220, 0.16); overflow: hidden; }
.loader-bar i {
  display: block; width: 0%; height: 100%;
  background: linear-gradient(90deg, var(--blue), var(--cyan));
  box-shadow: 0 0 16px var(--cyan);
  transition: width 0.28s ease;
}
.loader-status {
  font-family: var(--font-display); font-size: 8px; letter-spacing: 0.28em; color: var(--muted);
}

/* ------- shared buttons ------- */
.icon-btn {
  width: 44px; height: 44px; display: grid; place-items: center;
  border: 1px solid rgba(115, 206, 235, 0.22);
  background: rgba(3, 12, 22, 0.5);
  color: var(--muted);
  transition: 0.2s ease;
  clip-path: polygon(8px 0, 100% 0, 100% calc(100% - 8px), calc(100% - 8px) 100%, 0 100%, 0 8px);
}
.icon-btn:hover { color: var(--cyan); border-color: rgba(46, 231, 255, 0.6); background: rgba(12, 42, 60, 0.65); }
.icon-btn svg { width: 20px; height: 20px; fill: currentColor; }
.icon-btn .sound-off { display: none; }
body.muted .icon-btn .sound-on { display: none; }
body.muted .icon-btn .sound-off { display: block; }
.icon-btn.small { width: 36px; height: 36px; }

/* ------- menu shell ------- */
.menu {
  position: absolute; inset: 0; z-index: 10;
  display: flex; flex-direction: column;
  padding: calc(22px + var(--safe-t)) calc(34px + var(--safe-r)) calc(16px + var(--safe-b)) calc(34px + var(--safe-l));
  overflow: hidden;
  background:
    radial-gradient(ellipse at 74% 52%, transparent 22%, rgba(2, 7, 14, 0.24) 64%),
    linear-gradient(90deg, rgba(2, 7, 14, 0.8) 0%, rgba(2, 7, 14, 0.24) 46%, transparent 64%);
  animation: menuIn 0.7s cubic-bezier(0.2, 0.75, 0.2, 1) both;
}
@keyframes menuIn { from { opacity: 0; } to { opacity: 1; } }
.menu-top { display: flex; justify-content: space-between; align-items: flex-start; gap: 20px; flex: none; }
.brand { display: flex; align-items: center; gap: 14px; }
.brand-mark {
  width: 54px; height: 60px; color: var(--cyan); display: grid; place-items: center;
  filter: drop-shadow(0 0 18px rgba(46, 231, 255, 0.45));
}
.brand-mark svg { width: 100%; height: 100%; }
.brand-text h1 {
  margin: 0; font-family: var(--font-display); font-size: clamp(20px, 2.2vw, 31px);
  font-weight: 900; letter-spacing: 0.05em; line-height: 1; font-style: italic;
}
.brand-text h1 span { color: var(--cyan); margin-left: 6px; text-shadow: 0 0 22px rgba(46, 231, 255, 0.55); }
.brand-text p {
  margin: 7px 0 0; font-family: var(--font-display); font-size: 7.5px; letter-spacing: 0.34em; color: var(--muted);
}
.brand-text p b { color: var(--orange); }
.top-actions { display: flex; align-items: center; gap: 12px; }
.season-chip {
  display: flex; align-items: center; gap: 8px; height: 30px; padding: 0 12px;
  font-family: var(--font-display); font-size: 8px; letter-spacing: 0.18em; color: #9eb5c6;
  border: 1px solid rgba(111, 206, 235, 0.16); background: rgba(3, 12, 22, 0.46);
}
.season-chip i { width: 5px; height: 5px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 8px var(--cyan); animation: blink 1.8s infinite; }
.season-chip span { color: var(--orange); }
@keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: 0.25; } }

.menu-main {
  display: grid;
  grid-template-columns: minmax(560px, 660px) 1fr;
  gap: 32px;
  align-items: end;
  flex: 1;
  min-height: 0;
  padding: 18px 0 12px;
}
.garage { padding: 18px 18px 16px; min-height: 0; position: relative; }
.garage::before {
  content: ''; position: absolute; inset: -1px; pointer-events: none;
  background: linear-gradient(120deg, rgba(46, 231, 255, 0.55), transparent 18%, transparent 82%, rgba(255, 122, 31, 0.35));
  -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
  -webkit-mask-composite: xor; mask-composite: exclude; padding: 1px;
}
.garage-head { display: flex; justify-content: space-between; align-items: flex-start; gap: 14px; }
.garage-head h2 {
  margin: 3px 0 0; font-family: var(--font-display); font-size: 28px; font-weight: 900;
  letter-spacing: 0.06em; font-style: italic; line-height: 1;
}
.garage-note {
  display: flex; align-items: center; gap: 7px; font-family: var(--font-display);
  font-size: 7px; letter-spacing: 0.14em; color: #86a1b4; text-align: right; max-width: 160px; line-height: 1.6;
}
.pulse-dot { width: 5px; height: 5px; flex: none; border-radius: 50%; background: var(--orange); box-shadow: 0 0 9px var(--orange); animation: blink 1.4s infinite; }
.tabs { display: flex; gap: 4px; margin: 16px 0 12px; border-bottom: 1px solid rgba(105, 196, 226, 0.14); }
.tab {
  position: relative; padding: 8px 13px 10px; font-family: var(--font-display);
  font-size: 8px; font-weight: 700; letter-spacing: 0.16em; color: #6e899d; transition: 0.18s;
}
.tab:hover { color: #b9dceb; }
.tab.active { color: var(--cyan); text-shadow: 0 0 16px rgba(46, 231, 255, 0.4); }
.tab.active::after {
  content: ''; position: absolute; left: 9px; right: 9px; bottom: -1px; height: 2px;
  background: var(--cyan); box-shadow: 0 0 12px var(--cyan);
}
.tab .tab-count { font-size: 6px; color: #476477; margin-left: 5px; vertical-align: top; }
.garage-grid { display: grid; grid-template-columns: 1.25fr 0.9fr; gap: 14px; min-height: 0; }
.items {
  display: grid; grid-template-columns: 1fr 1fr; gap: 8px; align-content: start;
  max-height: 310px; overflow-y: auto; padding: 2px 4px 4px 2px;
  scrollbar-width: thin; scrollbar-color: rgba(46, 231, 255, 0.3) transparent;
}
.items::-webkit-scrollbar { width: 4px; }
.items::-webkit-scrollbar-thumb { background: rgba(46, 231, 255, 0.25); }
.item-card {
  position: relative; text-align: left; min-height: 88px; padding: 10px;
  display: grid; grid-template-columns: 38px 1fr; grid-template-rows: auto 1fr; gap: 7px 9px;
  border: 1px solid rgba(110, 196, 225, 0.13);
  background: linear-gradient(145deg, rgba(14, 34, 53, 0.55), rgba(4, 12, 21, 0.55));
  transition: transform 0.16s ease, border-color 0.16s, background 0.16s, box-shadow 0.16s;
  overflow: hidden;
}
.item-card::before {
  content: ''; position: absolute; inset: 0; opacity: 0;
  background: radial-gradient(circle at 18% 20%, var(--accent, #2ee7ff), transparent 62%);
  mix-blend-mode: screen; transition: opacity 0.2s;
}
.item-card:hover { transform: translateY(-2px); border-color: rgba(113, 218, 248, 0.42); background: linear-gradient(145deg, rgba(20, 48, 69, 0.7), rgba(6, 17, 29, 0.7)); }
.item-card:hover::before { opacity: 0.12; }
.item-card.selected {
  border-color: var(--accent, var(--cyan));
  box-shadow: inset 0 0 24px rgba(46, 231, 255, 0.08), 0 0 20px rgba(46, 231, 255, 0.09);
}
.item-card.selected::after {
  content: ''; position: absolute; top: 0; left: 0; width: 3px; height: 100%;
  background: var(--accent, var(--cyan)); box-shadow: 0 0 12px var(--accent, var(--cyan));
}
.item-icon {
  width: 38px; height: 38px; display: grid; place-items: center; border: 1px solid rgba(125, 211, 235, 0.16);
  background: rgba(3, 12, 21, 0.55); color: var(--accent, var(--cyan));
}
.item-icon svg { width: 28px; height: 28px; }
.item-meta { display: flex; flex-direction: column; justify-content: center; min-width: 0; }
.item-meta strong { font-size: 14px; font-weight: 700; letter-spacing: 0.02em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.item-meta span { font-family: var(--font-display); font-size: 6px; letter-spacing: 0.15em; color: var(--muted); margin-top: 3px; }
.item-mods { grid-column: 1 / -1; display: flex; align-items: center; gap: 4px; flex-wrap: wrap; }
.mod-chip {
  font-family: var(--font-display); font-size: 6px; letter-spacing: 0.06em; padding: 3px 5px;
  background: rgba(46, 231, 255, 0.09); color: #8feaff; border: 1px solid rgba(46, 231, 255, 0.14);
}
.mod-chip.neg { background: rgba(255, 77, 110, 0.07); color: #ff8ca1; border-color: rgba(255, 77, 110, 0.14); }
.telemetry {
  border-left: 1px solid rgba(110, 196, 225, 0.13);
  padding-left: 14px; display: flex; flex-direction: column; min-width: 0;
}
.telemetry-head { display: flex; justify-content: space-between; align-items: center; gap: 6px; }
.telemetry-head > span:last-child {
  font-family: var(--font-display); font-size: 6.5px; letter-spacing: 0.12em; color: var(--orange);
}
.stat-list { margin: 14px 0 4px; display: flex; flex-direction: column; gap: 10px; }
.stat-row { display: grid; grid-template-columns: 58px 1fr 30px; align-items: center; gap: 8px; }
.stat-row > span { font-family: var(--font-display); font-size: 6.5px; letter-spacing: 0.1em; color: #7e99ac; }
.stat-row > b { font-family: var(--font-display); font-size: 9px; text-align: right; color: #d9f7ff; font-weight: 700; }
.stat-track { height: 5px; background: rgba(100, 180, 210, 0.13); position: relative; overflow: hidden; }
.stat-fill {
  display: block; height: 100%; width: 50%;
  background: linear-gradient(90deg, #1b6bff, var(--cyan));
  box-shadow: 0 0 9px rgba(46, 231, 255, 0.45);
  transition: width 0.35s cubic-bezier(0.2, 0.8, 0.2, 1);
}
.stat-track::after {
  content: ''; position: absolute; inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0 15%, rgba(2, 8, 14, 0.8) 15% 16.5%);
}
.loadout-line {
  margin-top: auto; padding-top: 12px; border-top: 1px solid rgba(110, 196, 225, 0.1);
  font-family: var(--font-display); font-size: 6px; letter-spacing: 0.09em; color: #5f7e93;
  line-height: 1.6; text-transform: uppercase;
}
.tradeoff {
  margin-top: 7px; font-size: 11px; line-height: 1.25; color: #86a1b4; min-height: 28px;
}
.tradeoff b { color: var(--cyan); font-weight: 600; }
.tradeoff i { color: #ff8ca1; font-style: normal; font-weight: 600; }

.hero-side { display: flex; justify-content: flex-end; align-items: flex-end; min-width: 0; }
.hero-card { width: min(390px, 100%); padding: 18px 20px 20px; position: relative; }
.hero-card::before {
  content: ''; position: absolute; left: 0; top: 22px; bottom: 22px; width: 2px;
  background: linear-gradient(180deg, transparent, var(--orange), transparent);
  box-shadow: 0 0 12px var(--orange);
}
.hero-card-top { display: flex; justify-content: space-between; align-items: center; gap: 12px; }
.hero-rank { font-family: var(--font-display); font-size: 7px; letter-spacing: 0.11em; color: #ffd29a; display: flex; gap: 6px; align-items: center; }
.hero-rank i { width: 6px; height: 6px; background: var(--orange); transform: rotate(45deg); box-shadow: 0 0 8px var(--orange); }
.hero-card h2 {
  margin: 9px 0 3px; font-family: var(--font-display); font-size: 36px; font-weight: 900;
  font-style: italic; letter-spacing: 0.03em; line-height: 1; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
}
.hero-card > p { margin: 0; font-size: 13px; line-height: 1.35; color: #93aabd; min-height: 34px; }
.hero-tags { display: flex; flex-wrap: wrap; gap: 5px; margin: 10px 0 14px; min-height: 20px; }
.hero-tags span {
  font-family: var(--font-display); font-size: 6px; letter-spacing: 0.1em; padding: 4px 7px;
  border: 1px solid rgba(46, 231, 255, 0.18); color: #a5e9f8; background: rgba(46, 231, 255, 0.05);
}
.setup-row { display: flex; flex-direction: column; gap: 7px; padding-top: 13px; border-top: 1px solid rgba(110, 196, 225, 0.12); }
.setup-label { font-family: var(--font-display); font-size: 6.5px; letter-spacing: 0.17em; color: #6f8da1; }
.difficulty { display: grid; grid-template-columns: repeat(3, 1fr); gap: 3px; }
.difficulty button {
  font-family: var(--font-display); font-size: 7px; letter-spacing: 0.08em; color: #6f8da1;
  border: 1px solid rgba(110, 196, 225, 0.14); padding: 7px 2px; transition: 0.18s;
}
.difficulty button:hover { color: #c8e9f5; border-color: rgba(46, 231, 255, 0.4); }
.difficulty button.active { color: var(--ink); background: var(--cyan); border-color: var(--cyan); box-shadow: 0 0 18px rgba(46, 231, 255, 0.25); }
.play-btn {
  position: relative; width: 100%; margin-top: 14px; min-height: 62px; display: flex; align-items: center; gap: 13px;
  padding: 9px 16px; overflow: hidden; text-align: left;
  background: linear-gradient(100deg, #1a7dff 0%, #25d7ff 58%, #89f7ff 100%);
  color: #02121b; clip-path: polygon(10px 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%, 0 10px);
  transition: transform 0.18s, filter 0.18s;
}
.play-btn:hover { transform: translateY(-2px); filter: brightness(1.1); }
.play-btn:active { transform: translateY(0); }
.play-icon { width: 36px; height: 36px; display: grid; place-items: center; border: 1px solid rgba(0, 20, 30, 0.35); background: rgba(0, 32, 44, 0.12); flex: none; }
.play-icon svg { width: 20px; height: 20px; fill: #02121b; }
.play-copy { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
.play-copy b { font-family: var(--font-display); font-size: 12px; letter-spacing: 0.09em; white-space: nowrap; }
.play-copy small { font-family: var(--font-display); font-size: 6px; letter-spacing: 0.16em; opacity: 0.66; }
.play-shine {
  position: absolute; top: -50%; bottom: -50%; width: 40px; left: -60px; transform: skewX(-22deg);
  background: rgba(255, 255, 255, 0.5); filter: blur(8px); animation: shine 3.6s ease-in-out infinite 1.2s;
}
@keyframes shine { 0%, 66% { left: -20%; } 88%, 100% { left: 120%; } }

.menu-footer {
  flex: none; display: flex; align-items: flex-end; justify-content: space-between; gap: 18px;
  padding-top: 10px; border-top: 1px solid rgba(104, 196, 226, 0.1);
}
.controls-strip { display: flex; gap: 19px; flex-wrap: wrap; }
.controls-strip > div { display: flex; align-items: center; gap: 4px; }
.controls-strip span { font-family: var(--font-display); font-size: 6px; letter-spacing: 0.13em; color: #6d8b9f; margin-left: 3px; }
kbd {
  display: inline-grid; place-items: center; min-width: 18px; height: 18px; padding: 0 4px;
  font-family: var(--font-display); font-size: 6.5px; color: #b6d8e6;
  border: 1px solid rgba(117, 205, 235, 0.22); background: rgba(5, 17, 28, 0.6);
}
kbd.wide { padding: 0 6px; }
.footer-note { font-family: var(--font-display); font-size: 7px; letter-spacing: 0.26em; color: #47778c; white-space: nowrap; }

/* ------- HUD ------- */
.hud { position: absolute; inset: 0; z-index: 8; pointer-events: none; }
.hud button { pointer-events: auto; }
.score-wrap { position: absolute; top: calc(14px + var(--safe-t)); left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; }
.scoreboard {
  display: flex; align-items: stretch; filter: drop-shadow(0 12px 24px rgba(0, 0, 0, 0.5));
}
.team {
  min-width: 86px; height: 54px; display: flex; align-items: center; justify-content: center; gap: 10px; padding: 0 14px;
  background: rgba(4, 13, 23, 0.78); border: 1px solid rgba(130, 218, 245, 0.16);
  backdrop-filter: blur(12px);
}
.team.blue { clip-path: polygon(0 0, 100% 0, calc(100% - 10px) 100%, 0 100%); border-right: 0; }
.team.orange { clip-path: polygon(10px 0, 100% 0, 100% 100%, 0 100%); border-left: 0; }
.team b { font-family: var(--font-display); font-size: 28px; font-weight: 900; line-height: 1; color: var(--white); }
.team.blue b { color: #82d8ff; text-shadow: 0 0 18px rgba(45, 131, 255, 0.6); }
.team.orange b { color: #ffb15c; text-shadow: 0 0 18px rgba(255, 122, 31, 0.5); }
.team-tag { font-family: var(--font-display); font-size: 7px; letter-spacing: 0.16em; color: #7e9caf; }
.clock-wrap {
  min-width: 104px; display: flex; flex-direction: column; align-items: center; justify-content: center;
  background: linear-gradient(180deg, rgba(13, 42, 61, 0.92), rgba(5, 16, 27, 0.92));
  border-top: 1px solid rgba(46, 231, 255, 0.3); border-bottom: 1px solid rgba(46, 231, 255, 0.3);
  clip-path: polygon(9px 0, calc(100% - 9px) 0, 100% 50%, calc(100% - 9px) 100%, 9px 100%, 0 50%);
}
.clock-wrap span { font-family: var(--font-display); font-size: 5.5px; letter-spacing: 0.18em; color: var(--cyan); }
.clock-wrap strong { font-family: var(--font-display); font-size: 19px; letter-spacing: 0.06em; color: #e9fbff; line-height: 1.2; }
.clock-wrap.hurry strong { color: var(--orange); animation: hurry 1s infinite; }
.clock-wrap.overtime strong { color: var(--pink); }
@keyframes hurry { 50% { opacity: 0.45; } }
.objective {
  margin-top: 7px; padding: 4px 12px; font-family: var(--font-display); font-size: 6px; letter-spacing: 0.16em;
  color: #86a4b6; background: rgba(3, 11, 20, 0.55); border: 1px solid rgba(100, 190, 220, 0.1);
}
.top-right { position: absolute; top: calc(18px + var(--safe-t)); right: calc(20px + var(--safe-r)); display: flex; align-items: center; gap: 10px; pointer-events: auto; }
.cam-chip {
  display: flex; align-items: center; gap: 7px; height: 30px; padding: 0 11px;
  font-family: var(--font-display); font-size: 6.5px; letter-spacing: 0.1em; color: #9fbdcb;
  background: rgba(4, 13, 23, 0.62); border: 1px solid rgba(110, 196, 225, 0.16); backdrop-filter: blur(8px);
}
.cam-chip span { width: 5px; height: 5px; border-radius: 50%; background: var(--cyan); box-shadow: 0 0 7px var(--cyan); }
.cam-chip.car span { background: var(--orange); box-shadow: 0 0 7px var(--orange); }

.boost-hud { position: absolute; left: calc(28px + var(--safe-l)); bottom: calc(25px + var(--safe-b)); width: 260px; }
.boost-label { display: flex; align-items: baseline; justify-content: space-between; font-family: var(--font-display); color: #8baabd; letter-spacing: 0.15em; font-size: 7px; }
.boost-label b { color: var(--orange-soft); font-size: 18px; line-height: 1; text-shadow: 0 0 14px rgba(255, 150, 40, 0.4); }
.boost-track { position: relative; height: 10px; margin-top: 5px; background: rgba(7, 20, 32, 0.85); border: 1px solid rgba(255, 165, 74, 0.28); overflow: hidden; }
.boost-track i {
  display: block; height: 100%; width: 34%;
  background: linear-gradient(90deg, #ff6a00, #ffb730 65%, #fff1b0);
  box-shadow: 0 0 18px rgba(255, 140, 30, 0.7); transition: width 0.1s linear;
}
.boost-ticks { position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 9%, rgba(3, 9, 15, 0.85) 9% 10%); }
.boost-sub { display: flex; justify-content: space-between; margin-top: 5px; font-family: var(--font-display); font-size: 5.5px; letter-spacing: 0.14em; color: #5f7f92; }
.boost-sub #regenTag { color: var(--cyan); }
.speed-hud { position: absolute; left: 50%; bottom: calc(20px + var(--safe-b)); transform: translateX(-50%); width: 170px; text-align: center; }
.speed-num { display: flex; align-items: baseline; justify-content: center; gap: 5px; }
.speed-num b { font-family: var(--font-display); font-size: 27px; line-height: 1; letter-spacing: 0.03em; color: #dff8ff; font-style: italic; }
.speed-num span { font-family: var(--font-display); font-size: 6px; letter-spacing: 0.1em; color: #69879a; }
.speed-foot { display: flex; align-items: center; gap: 7px; margin-top: 4px; }
.speed-foot span { font-family: var(--font-display); font-size: 5.5px; letter-spacing: 0.16em; color: #57778b; white-space: nowrap; }
.speed-foot i { height: 3px; flex: 1; background: rgba(46, 231, 255, 0.12); position: relative; overflow: hidden; }
.speed-foot i::after { content: ''; position: absolute; inset: 0; width: var(--speed, 0%); background: linear-gradient(90deg, var(--blue), var(--cyan)); box-shadow: 0 0 8px var(--cyan); }
.speed-hud.sonic .speed-num b { color: var(--cyan); text-shadow: 0 0 19px rgba(46, 231, 255, 0.65); }
.ability-hud { position: absolute; right: calc(28px + var(--safe-r)); bottom: calc(26px + var(--safe-b)); display: flex; gap: 5px; }
.pip { padding: 6px 9px; border: 1px solid rgba(110, 196, 225, 0.12); background: rgba(4, 13, 23, 0.55); opacity: 0.42; transition: 0.15s; }
.pip span { font-family: var(--font-display); font-size: 5.5px; letter-spacing: 0.1em; color: #8aa9bb; }
.pip.active { opacity: 1; border-color: rgba(46, 231, 255, 0.34); }
.pip.active span { color: var(--cyan); }

.center-msg {
  position: absolute; top: 31%; left: 50%; transform: translate(-50%, -50%) scale(0.9);
  font-family: var(--font-display); font-size: clamp(48px, 9vw, 120px); font-weight: 900; font-style: italic;
  letter-spacing: 0.02em; color: #fff; opacity: 0; transition: opacity 0.18s, transform 0.18s;
  text-shadow: 0 0 40px rgba(46, 231, 255, 0.7), 0 10px 30px rgba(0, 0, 0, 0.6);
}
.center-msg.show { opacity: 1; transform: translate(-50%, -50%) scale(1); }
.center-msg.go { color: var(--cyan); }
.center-msg.warn { color: var(--orange); }
.goal-banner {
  position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center;
  opacity: 0; visibility: hidden; transition: 0.3s; background: radial-gradient(ellipse at center, transparent 18%, rgba(0, 4, 10, 0.5) 80%);
}
.goal-banner.show { opacity: 1; visibility: visible; }
.goal-banner span {
  font-family: var(--font-display); font-size: clamp(30px, 5vw, 66px); font-style: italic; font-weight: 900;
  letter-spacing: 0.08em; color: var(--cyan); text-shadow: 0 0 48px rgba(46, 231, 255, 0.8);
  transform: skewX(-8deg); animation: bannerIn 0.5s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.goal-banner.orange span { color: var(--orange); text-shadow: 0 0 48px rgba(255, 122, 31, 0.8); }
.goal-banner b {
  font-family: var(--font-display); font-size: clamp(10px, 1.4vw, 17px); letter-spacing: 0.4em; color: #e9fbff; margin-top: 10px;
  animation: bannerIn 0.6s 0.06s cubic-bezier(0.16, 1, 0.3, 1) both;
}
.goal-banner i { width: min(380px, 60vw); height: 2px; margin-top: 14px; background: linear-gradient(90deg, transparent, var(--cyan), transparent); box-shadow: 0 0 22px var(--cyan); animation: lineGrow 0.7s 0.1s both; }
.goal-banner.orange i { background: linear-gradient(90deg, transparent, var(--orange), transparent); box-shadow: 0 0 22px var(--orange); }
@keyframes bannerIn { from { opacity: 0; transform: translateY(22px) skewX(-8deg) scale(0.94); } to { opacity: 1; transform: translateY(0) skewX(-8deg) scale(1); } }
@keyframes lineGrow { from { transform: scaleX(0); } to { transform: scaleX(1); } }
.toast {
  position: absolute; top: 23%; left: 50%; transform: translateX(-50%) translateY(-10px);
  font-family: var(--font-display); font-size: 9px; letter-spacing: 0.16em; color: #d9f8ff;
  background: rgba(4, 14, 24, 0.78); border: 1px solid rgba(46, 231, 255, 0.25); padding: 8px 14px;
  opacity: 0; transition: 0.25s; pointer-events: none; white-space: nowrap;
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }

/* ------- touch ------- */
.touch-ui { display: none; }
body.touch .touch-ui { display: block; }
body.touch .controls-strip { display: none; }
body.touch .ability-hud { display: none; }
body.touch .speed-hud { bottom: calc(158px + var(--safe-b)); left: calc(22px + var(--safe-l)); transform: none; text-align: left; width: 130px; }
body.touch .boost-hud { left: 50%; transform: translateX(-50%); bottom: calc(16px + var(--safe-b)); width: 220px; }
.stick-base {
  position: absolute; left: calc(26px + var(--safe-l)); bottom: calc(26px + var(--safe-b));
  width: 118px; height: 118px; border-radius: 50%; pointer-events: auto; touch-action: none;
  background: radial-gradient(circle, rgba(13, 40, 58, 0.5), rgba(4, 14, 24, 0.55) 70%);
  border: 1px solid rgba(46, 231, 255, 0.23); box-shadow: inset 0 0 30px rgba(46, 231, 255, 0.06);
  display: flex; align-items: center; justify-content: center;
}
.stick-ring { position: absolute; inset: 15px; border-radius: 50%; border: 1px dashed rgba(46, 231, 255, 0.18); }
.stick-knob {
  width: 50px; height: 50px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, #a8f4ff, #23a8d4 48%, #0a526f);
  box-shadow: 0 0 22px rgba(46, 231, 255, 0.45); transition: transform 0.06s linear;
}
.stick-base > span {
  position: absolute; bottom: -17px; font-family: var(--font-display); font-size: 5.5px;
  letter-spacing: 0.2em; color: #6b8b9e;
}
.touch-buttons { position: absolute; right: calc(22px + var(--safe-r)); bottom: calc(22px + var(--safe-b)); width: 176px; height: 146px; pointer-events: auto; }
.tbtn {
  position: absolute; border-radius: 50%; border: 1px solid rgba(120, 210, 240, 0.28);
  font-family: var(--font-display); font-size: 7px; letter-spacing: 0.06em; color: #d8f7ff;
  background: radial-gradient(circle at 36% 30%, rgba(38, 105, 132, 0.72), rgba(4, 15, 26, 0.82));
  box-shadow: 0 0 18px rgba(0, 0, 0, 0.35), inset 0 0 18px rgba(46, 231, 255, 0.05);
  touch-action: none; user-select: none;
}
.tbtn:active, .tbtn.held { background: radial-gradient(circle at 36% 30%, rgba(80, 190, 220, 0.9), rgba(8, 50, 70, 0.9)); box-shadow: 0 0 22px rgba(46, 231, 255, 0.4); }
.tbtn small { display: block; font-size: 5px; opacity: 0.6; }
.tbtn.boost { width: 78px; height: 78px; right: 0; bottom: 0; color: #ffd39f; border-color: rgba(255, 154, 42, 0.45); background: radial-gradient(circle at 36% 30%, rgba(117, 62, 16, 0.8), rgba(24, 12, 5, 0.86)); font-size: 8px; }
.tbtn.boost:active, .tbtn.boost.held { background: radial-gradient(circle at 36% 30%, rgba(255, 170, 50, 0.95), rgba(102, 47, 4, 0.9)); box-shadow: 0 0 26px rgba(255, 140, 30, 0.6); }
.tbtn.jump { width: 60px; height: 60px; right: 82px; bottom: 12px; }
.tbtn.drift { width: 48px; height: 48px; right: 54px; bottom: 84px; font-size: 6px; }
.tbtn.cam { width: 43px; height: 43px; right: 0; bottom: 84px; font-size: 6px; }

/* ------- modals ------- */
.modal-wrap {
  position: absolute; inset: 0; z-index: 30; display: flex; align-items: center; justify-content: center;
  background: radial-gradient(ellipse at center, rgba(3, 11, 20, 0.4), rgba(0, 3, 8, 0.82));
  backdrop-filter: blur(6px); padding: 20px;
}
.modal { width: min(430px, 100%); padding: 28px; text-align: center; animation: modalIn 0.32s cubic-bezier(0.16, 1, 0.3, 1) both; }
@keyframes modalIn { from { opacity: 0; transform: translateY(16px) scale(0.97); } to { opacity: 1; transform: none; } }
.modal h2 { margin: 8px 0 14px; font-family: var(--font-display); font-size: 42px; font-style: italic; font-weight: 900; letter-spacing: 0.04em; line-height: 1; }
.pause-score { display: flex; align-items: center; justify-content: center; gap: 16px; margin: 0 0 22px; padding: 12px 0; border-top: 1px solid rgba(110, 196, 225, 0.12); border-bottom: 1px solid rgba(110, 196, 225, 0.12); }
.pause-score span { font-family: var(--font-display); font-size: 8px; letter-spacing: 0.14em; color: #7997a9; display: flex; align-items: center; gap: 7px; }
.pause-score b { font-size: 25px; color: var(--white); }
.pause-score .blue b { color: #82d8ff; }
.pause-score .orange b { color: #ffb15c; }
.pause-score i { font-family: var(--font-display); font-size: 7px; color: #4d6c7f; font-style: normal; }
.modal-btn {
  width: 100%; height: 43px; margin-top: 7px; font-family: var(--font-display); font-size: 9px; font-weight: 700;
  letter-spacing: 0.16em; color: #a9cad9; border: 1px solid rgba(110, 196, 225, 0.2); background: rgba(7, 20, 32, 0.6);
  transition: 0.18s; clip-path: polygon(7px 0, 100% 0, 100% calc(100% - 7px), calc(100% - 7px) 100%, 0 100%, 0 7px);
}
.modal-btn:hover { color: #fff; border-color: rgba(46, 231, 255, 0.5); background: rgba(15, 46, 63, 0.7); }
.modal-btn.primary { color: #03121b; background: linear-gradient(100deg, #2d83ff, #2ee7ff); border-color: transparent; }
.modal-btn.primary:hover { filter: brightness(1.12); color: #03121b; }
.modal-btn.ghost { border-color: transparent; color: #5f8296; }
.modal-foot { margin-top: 18px; font-family: var(--font-display); font-size: 5.5px; letter-spacing: 0.15em; color: #4b6b7e; line-height: 1.7; }
.end-modal h2 { color: var(--cyan); text-shadow: 0 0 30px rgba(46, 231, 255, 0.35); }
.end-modal h2.loss { color: var(--orange); text-shadow: 0 0 30px rgba(255, 122, 31, 0.3); }
.end-score { display: flex; align-items: center; justify-content: center; gap: 18px; margin: 4px 0 18px; }
.end-score span { font-family: var(--font-display); font-size: 46px; font-weight: 900; font-style: italic; }
.end-score span:first-child { color: #82d8ff; text-shadow: 0 0 24px rgba(45, 131, 255, 0.4); }
.end-score span:last-child { color: #ffb15c; text-shadow: 0 0 24px rgba(255, 122, 31, 0.35); }
.end-score i { font-family: var(--font-display); font-size: 17px; color: #45697d; font-style: normal; }
.end-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 5px; margin-bottom: 18px; }
.end-stat { text-align: left; padding: 8px 10px; border: 1px solid rgba(110, 196, 225, 0.12); background: rgba(5, 18, 30, 0.5); }
.end-stat span { display: block; font-family: var(--font-display); font-size: 5.5px; letter-spacing: 0.14em; color: #638397; }
.end-stat b { font-family: var(--font-display); font-size: 15px; color: #d9f6ff; }
.end-actions { display: grid; grid-template-columns: 1.2fr 1fr; gap: 6px; }
.end-actions .modal-btn { margin: 0; }
.rotate-hint {
  position: absolute; bottom: 10px; left: 50%; transform: translateX(-50%); z-index: 40;
  font-family: var(--font-display); font-size: 7px; letter-spacing: 0.12em; color: #7e9eb2;
  background: rgba(3, 12, 20, 0.8); padding: 8px 14px; border: 1px solid rgba(46, 231, 255, 0.18);
}

/* ------- responsive ------- */
@media (max-width: 1180px) {
  .menu-main { grid-template-columns: minmax(480px, 590px) 1fr; gap: 22px; }
  .garage { padding: 15px; }
  .garage-grid { grid-template-columns: 1.15fr 0.95fr; gap: 10px; }
  .items { max-height: 285px; }
  .hero-card { width: 330px; padding: 16px; }
  .hero-card h2 { font-size: 30px; }
}
@media (max-width: 940px), (max-height: 640px) and (pointer: coarse) {
  .menu { overflow-y: auto; padding-top: calc(12px + var(--safe-t)); justify-content: flex-start; }
  .menu-main { grid-template-columns: 1fr; align-items: start; gap: 14px; flex: none; padding-top: 12px; }
  .garage { width: 100%; }
  .garage-grid { grid-template-columns: 1fr; }
  .items { grid-template-columns: repeat(2, 1fr); max-height: none; }
  .telemetry { border-left: 0; border-top: 1px solid rgba(110, 196, 225, 0.13); padding-left: 0; padding-top: 12px; }
  .stat-list { display: grid; grid-template-columns: 1fr 1fr; gap: 8px 16px; }
  .loadout-line { margin-top: 8px; }
  .tradeoff { min-height: 0; }
  .hero-side { justify-content: stretch; }
  .hero-card { width: 100%; max-width: none; }
  .menu-footer { margin-top: 16px; }
  .season-chip { display: none; }
  .brand-text h1 { font-size: 20px; }
  .brand-text p { font-size: 6px; letter-spacing: 0.24em; }
}
@media (max-width: 700px) {
  .menu { padding-left: calc(12px + var(--safe-l)); padding-right: calc(12px + var(--safe-r)); }
  .menu-top { align-items: center; }
  .brand-mark { width: 38px; height: 43px; }
  .brand-text h1 { font-size: 17px; }
  .brand-text p { display: none; }
  .garage-head h2 { font-size: 23px; }
  .garage-note { font-size: 5.5px; max-width: 120px; }
  .items { display: flex; gap: 7px; overflow-x: auto; overflow-y: hidden; padding-bottom: 7px; }
  .item-card { flex: 0 0 146px; min-height: 92px; }
  .stat-row { grid-template-columns: 50px 1fr 27px; }
  .hero-card h2 { font-size: 27px; }
  .hero-card > p { min-height: 0; font-size: 12px; }
  .play-btn { min-height: 58px; }
  .score-wrap { top: calc(8px + var(--safe-t)); }
  .team { min-width: 62px; height: 46px; padding: 0 9px; }
  .team b { font-size: 22px; }
  .team-tag { display: none; }
  .clock-wrap { min-width: 82px; }
  .clock-wrap strong { font-size: 15px; }
  .objective { display: none; }
  .top-right { top: calc(10px + var(--safe-t)); right: calc(10px + var(--safe-r)); gap: 5px; }
  .cam-chip { display: none; }
  .boost-hud { width: 190px; }
  .speed-hud { width: 120px; }
  .speed-num b { font-size: 22px; }
  .ability-hud { display: none; }
  .menu-footer { flex-direction: column; align-items: flex-start; gap: 6px; }
  .footer-note { font-size: 5.5px; }
  .touch-ui .stick-base { width: 104px; height: 104px; left: calc(16px + var(--safe-l)); }
  .stick-knob { width: 44px; height: 44px; }
  .touch-buttons { right: calc(13px + var(--safe-r)); width: 158px; height: 132px; }
  .tbtn.boost { width: 70px; height: 70px; }
  .tbtn.jump { width: 54px; height: 54px; right: 74px; }
  .tbtn.drift { width: 44px; height: 44px; right: 50px; bottom: 76px; }
  .tbtn.cam { width: 39px; height: 39px; right: 0; bottom: 76px; }
  .modal { padding: 22px 18px; }
  .modal h2 { font-size: 34px; }
}
@media (max-height: 760px) and (min-width: 941px) {
  .garage-head h2 { font-size: 23px; }
  .tabs { margin: 10px 0 9px; }
  .items { max-height: 250px; }
  .item-card { min-height: 78px; }
  .stat-list { gap: 7px; margin-top: 9px; }
  .hero-card h2 { font-size: 29px; }
  .hero-card { padding: 14px 16px 16px; }
  .menu-main { padding-top: 10px; padding-bottom: 8px; }
}
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after { animation-duration: 0.001ms !important; animation-iteration-count: 1 !important; }
}

