export function createArena(scene) {
  const root = new THREE.Group();
  root.name = 'arena';
  scene.add(root);

  const sky = makeSky();
  scene.add(sky);
  const stars = makeStars();
  scene.add(stars);
  const planet = makePlanet(scene);

  const fieldTex = makeFieldTexture();
  const fieldMat = new THREE.MeshStandardMaterial({
    map: fieldTex,
    emissive: 0x0c3a50,
    emissiveMap: fieldTex,
    emissiveIntensity: 0.52,
    roughness: 0.7,
    metalness: 0.12,
  });
  const field = new THREE.Mesh(new THREE.PlaneGeometry(FIELD.halfX * 2, FIELD.halfZ * 2), fieldMat);
  field.rotation.x = -Math.PI / 2;
  field.receiveShadow = true;
  root.add(field);

  // Under-field skirt
  const skirt = new THREE.Mesh(
    new THREE.BoxGeometry(FIELD.halfX * 2 + 4, 0.6, FIELD.halfZ * 2 + 4),
    new THREE.MeshStandardMaterial({ color: 0x03101a, metalness: 0.4, roughness: 0.7 }),
  );
  skirt.position.y = -0.32;
  root.add(skirt);

  const walls = makeWalls(root);
  makeStands(root);
  const crowd = makeCrowd(root);
  makeBarriers(root);
  const trusses = makeTrusses(root);
  const lights = makeLightTowers(root);
  const goals = { blue: makeGoal(root, TEAM.blue, -1), orange: makeGoal(root, TEAM.orange, 1) };
  const boostPads = makeBoostPads(root);
  const podium = makePodium(root);

  // Extra ground glow ring
  const centerGlow = new THREE.Mesh(
    new THREE.RingGeometry(7.8, 9.2, 64),
    new THREE.MeshBasicMaterial({ color: 0x2ee7ff, transparent: true, opacity: 0.08, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false }),
  );
  centerGlow.rotation.x = -Math.PI / 2;
  centerGlow.position.y = 0.025;
  root.add(centerGlow);

  const hemi = new THREE.HemisphereLight(0x7ec8e8, 0x061019, 1.35);
  scene.add(hemi);
  const key = new THREE.DirectionalLight(0xe6f9ff, 2.7);
  key.position.set(28, 48, 24);
  key.castShadow = true;
  key.shadow.mapSize.set(2048, 2048);
  key.shadow.camera.left = -70;
  key.shadow.camera.right = 70;
  key.shadow.camera.top = 70;
  key.shadow.camera.bottom = -70;
  key.shadow.camera.near = 1;
  key.shadow.camera.far = 140;
  key.shadow.bias = -0.0006;
  key.shadow.normalBias = 0.03;
  scene.add(key);
  const rim = new THREE.DirectionalLight(0xff8b3d, 0.9);
  rim.position.set(-30, 22, -36);
  scene.add(rim);
  const fill = new THREE.DirectionalLight(0x2d83ff, 0.85);
  fill.position.set(-24, 18, 30);
  scene.add(fill);

  const state = {
    root, field, walls, crowd, trusses, lights, goals, boostPads, podium,
    playerGoal: goals.blue,
    enemyGoal: goals.orange,
    time: 0,
    flash: { blue: 0, orange: 0 },
  };

  function setMenuMode(menu) {
    podium.visible = menu;
    centerGlow.visible = menu;
  }
  setMenuMode(true);

  function setGoalFlash(team, value) {
    state.flash[team] = Math.max(state.flash[team], value);
  }

  const clock = new THREE.Clock();
  function update(dt, elapsed) {
    state.time += dt;
    const t = state.time;
    for (let i = 0; i < boostPads.length; i += 1) {
      const pad = boostPads[i];
      pad.cooldown = Math.max(0, pad.cooldown - dt);
      const active = pad.cooldown <= 0;
      const bob = Math.sin(t * 2.2 + i * 1.7) * 0.11;
      pad.core.position.y = 0.62 + bob + (pad.big ? 0.12 : 0);
      pad.core.rotation.y += dt * 1.8;
      pad.core.rotation.x += dt * 0.7;
      pad.ring.rotation.z += dt * (pad.big ? 0.6 : -0.9);
      pad.ringMat.opacity = active ? 1 : 0.16;
      pad.discMat.opacity = active ? 0.2 + Math.sin(t * 3 + i) * 0.05 : 0.02;
      pad.coreMat.emissiveIntensity = active ? 5.5 : 0.5;
      pad.light.intensity = active ? (pad.big ? 9 : 4) : 0;
      const s = active ? 1 : 0.55;
      pad.group.scale.setScalar(THREE.MathUtils.lerp(pad.group.scale.x, s, dt * 6));
    }

    // Goal flash decay
    for (const key of ['blue', 'orange']) {
      state.flash[key] = Math.max(0, state.flash[key] - dt * 0.8);
      const f = state.flash[key];
      const goal = goals[key];
      goal.light.intensity = f * 130;
      goal.glowMat.emissiveIntensity = 4.2 + f * 12;
      goal.floorGlow.material.opacity = 0.08 + f * 0.45;
      goal.screen.material.opacity = 1;
    }

    planet.group.rotation.y += dt * 0.008;
    planet.ring.rotation.z += dt * 0.002;
    planet.moons.rotation.y += dt * 0.03;
    stars.rotation.y += dt * 0.0008;
    centerGlow.material.opacity = 0.06 + Math.sin(t * 1.4) * 0.02;
    podium.children.forEach((child) => {
      if (child.geometry && child.geometry.type === 'TorusGeometry') {
        child.rotation.z += dt * 0.15;
      }
    });
  }

  return { ...state, update, setMenuMode, setGoalFlash };
}

import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';
import { FIELD, TEAM } from './arena.js';

const UP = new THREE.Vector3(0, 1, 0);

function damp(current, target, lambda, dt) {
  return THREE.MathUtils.lerp(current, target, 1 - Math.exp(-lambda * dt));
}

function disposeGroup(group) {
  group.traverse((child) => {
    if (child.geometry) child.geometry.dispose();
    if (child.material) {
      const mats = Array.isArray(child.material) ? child.material : [child.material];
      mats.forEach((m) => {
        for (const key of Object.keys(m)) {
          const value = m[key];
          if (value && value.isTexture) value.dispose();
        }
        m.dispose();
      });
    }
  });
}

function buildBodyProfile(dims) {
  const L = dims.length;
  const H = dims.height;
  const C = dims.cabin;
  const shape = new THREE.Shape();
  shape.moveTo(-L / 2, 0.14);
  shape.lineTo(-L / 2, 0.58 + H * 0.15);
  shape.lineTo(-L * 0.36, 0.62 + H * 0.1);
  shape.lineTo(-L * 0.22, 0.66 + C * 0.92);
  shape.lineTo(-L * 0.05, 0.68 + C);
  shape.lineTo(L * 0.16, 0.62 + C * 0.72);
  shape.lineTo(L * 0.31, 0.56 + H * 0.42);
  shape.lineTo(L * 0.46, 0.48 + H * 0.22);
  shape.lineTo(L / 2, 0.33 + H * 0.06);
  shape.lineTo(L / 2, 0.16);
  shape.lineTo(-L / 2, 0.09);
  shape.closePath();
  return shape;
}

function makeNumberTexture(number, color) {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  ctx.clearRect(0, 0, 128, 128);
  ctx.strokeStyle = color;
  ctx.globalAlpha = 0.55;
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(64, 64, 45, 0, Math.PI * 2);
  ctx.stroke();
  ctx.globalAlpha = 0.92;
  ctx.fillStyle = color;
  ctx.font = '900 58px Orbitron, sans-serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(number, 64, 68);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

export function buildCarVisual(build, team, options = {}) {
  const { isPlayer = false, number = '07' } = options;
  const dims = build.chosen.body.dims;
  const accentColor = new THREE.Color(build.chosen.body.accent);
  const teamColor = new THREE.Color(team.color);
  const group = new THREE.Group();
  const bodyGroup = new THREE.Group();
  group.add(bodyGroup);

  const paintMat = new THREE.MeshPhysicalMaterial({
    color: teamColor,
    metalness: 0.58,
    roughness: 0.26,
    clearcoat: 1,
    clearcoatRoughness: 0.12,
    envMapIntensity: 1.4,
  });
  const accentMat = new THREE.MeshStandardMaterial({
    color: accentColor, emissive: accentColor, emissiveIntensity: 0.55,
    metalness: 0.55, roughness: 0.3,
  });
  const darkMat = new THREE.MeshStandardMaterial({ color: 0x060c12, metalness: 0.82, roughness: 0.34 });
  const carbonMat = new THREE.MeshStandardMaterial({ color: 0x0b141d, metalness: 0.6, roughness: 0.52 });
  const glassMat = new THREE.MeshPhysicalMaterial({
    color: 0x061824, metalness: 0.55, roughness: 0.07, transparent: true, opacity: 0.82,
    clearcoat: 1, clearcoatRoughness: 0.05, envMapIntensity: 1.8,
  });
  const glowMat = new THREE.MeshStandardMaterial({
    color: team.bright, emissive: team.bright, emissiveIntensity: 3.4, metalness: 0.3, roughness: 0.3,
  });
  const tailMat = new THREE.MeshStandardMaterial({
    color: 0xff2a2a, emissive: 0xff1a1a, emissiveIntensity: 3.6, metalness: 0.2, roughness: 0.35,
  });

  // Main extruded chassis
  const profile = buildBodyProfile(dims);
  const extrude = new THREE.ExtrudeGeometry(profile, {
    depth: dims.width, bevelEnabled: true, bevelThickness: 0.07, bevelSize: 0.055,
    bevelSegments: 3, curveSegments: 8,
  });
  extrude.computeVertexNormals();
  const chassis = new THREE.Mesh(extrude, paintMat);
  chassis.rotation.y = -Math.PI / 2;
  chassis.position.x = dims.width / 2;
  chassis.castShadow = true;
  chassis.receiveShadow = true;
  bodyGroup.add(chassis);

  // Glass canopy
  const canopy = new THREE.Mesh(
    new RoundedBoxGeometry(dims.width * 0.68, dims.cabin * 0.66, dims.length * 0.32, 4, 0.09),
    glassMat,
  );
  canopy.position.set(0, 0.66 + dims.cabin * 0.66, -dims.length * 0.04);
  canopy.rotation.x = -0.08;
  canopy.castShadow = true;
  bodyGroup.add(canopy);

  // Roof spine
  const roofSpine = new THREE.Mesh(
    new RoundedBoxGeometry(0.16, 0.055, dims.length * 0.25, 3, 0.02),
    accentMat,
  );
  roofSpine.position.set(0, 0.68 + dims.cabin * 1.02, -dims.length * 0.04);
  roofSpine.rotation.x = -0.06;
  bodyGroup.add(roofSpine);

  // Hood stripes
  for (const x of [-0.24, 0.24]) {
    const stripe = new THREE.Mesh(
      new RoundedBoxGeometry(0.07, 0.025, dims.length * 0.3, 2, 0.01),
      accentMat,
    );
    stripe.position.set(x, 0.56 + dims.height * 0.39, dims.length * 0.28);
    stripe.rotation.x = -0.11;
    bodyGroup.add(stripe);
  }

  // Nose splitter + side skirts
  const splitter = new THREE.Mesh(new THREE.BoxGeometry(dims.width * 0.92, 0.08, 0.42), carbonMat);
  splitter.position.set(0, 0.14, dims.length * 0.49);
  bodyGroup.add(splitter);
  for (const side of [-1, 1]) {
    const skirt = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.12, dims.length * 0.58), carbonMat);
    skirt.position.set(side * dims.width * 0.47, 0.24, 0);
    bodyGroup.add(skirt);
  }

  // Headlights
  for (const x of [-dims.width * 0.28, dims.width * 0.28]) {
    const light = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.13, 0.05), glowMat);
    light.position.set(x, 0.53, dims.length * 0.485);
    light.rotation.x = -0.35;
    bodyGroup.add(light);
  }
  // Tail lights
  for (const x of [-dims.width * 0.27, dims.width * 0.27]) {
    const light = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.10, 0.05), tailMat);
    light.position.set(x, 0.53, -dims.length * 0.49);
    bodyGroup.add(light);
  }

  // Rear wing
  const wingY = 0.6 + dims.height * 0.72;
  const wing = new THREE.Mesh(
    new RoundedBoxGeometry(dims.width * 0.9, 0.06, 0.34, 3, 0.025),
    carbonMat,
  );
  wing.position.set(0, wingY, -dims.length * 0.4);
  wing.rotation.x = -0.12;
  bodyGroup.add(wing);
  for (const x of [-dims.width * 0.3, dims.width * 0.3]) {
    const support = new THREE.Mesh(new THREE.BoxGeometry(0.07, 0.42, 0.16), carbonMat);
    support.position.set(x, wingY - 0.22, -dims.length * 0.4);
    bodyGroup.add(support);
  }
  const wingAccent = new THREE.Mesh(new THREE.BoxGeometry(dims.width * 0.86, 0.018, 0.05), accentMat);
  wingAccent.position.set(0, wingY + 0.045, -dims.length * 0.4);
  wingAccent.rotation.x = -0.12;
  bodyGroup.add(wingAccent);

  // Body-specific aero bits
  if (build.chosen.body.id === 'wasp') {
    for (const side of [-1, 1]) {
      const fin = new THREE.Mesh(new THREE.BoxGeometry(0.05, 0.38, 0.6), accentMat);
      fin.position.set(side * dims.width * 0.42, 0.68 + dims.height * 0.55, -dims.length * 0.25);
      fin.rotation.z = side * 0.25;
      bodyGroup.add(fin);
    }
  }
  if (build.chosen.body.id === 'merc') {
    const intake = new THREE.Mesh(new RoundedBoxGeometry(0.55, 0.18, 0.55, 3, 0.05), carbonMat);
    intake.position.set(0, 0.68 + dims.cabin * 1.05, -dims.length * 0.13);
    bodyGroup.add(intake);
    const scoop = new THREE.Mesh(new THREE.BoxGeometry(0.42, 0.08, 0.22), accentMat);
    scoop.position.set(0, 0.68 + dims.cabin * 1.15, -dims.length * 0.13);
    bodyGroup.add(scoop);
  }
  if (build.chosen.body.id === 'dominus') {
    const fin = new THREE.Mesh(new THREE.BoxGeometry(0.04, 0.22, 0.8), accentMat);
    fin.position.set(0, 0.68 + dims.cabin * 0.7, -dims.length * 0.29);
    bodyGroup.add(fin);
  }
  if (build.chosen.body.id === 'mantis') {
    for (const side of [-1, 1]) {
      const pod = new THREE.Mesh(new RoundedBoxGeometry(0.22, 0.18, 1.15, 3, 0.04), darkMat);
      pod.position.set(side * dims.width * 0.47, 0.38, -dims.length * 0.02);
      bodyGroup.add(pod);
    }
  }

  // Side number medallions
  const numberTex = makeNumberTexture(number, team.cssSoft);
  const numberMat = new THREE.MeshBasicMaterial({ map: numberTex, transparent: true, opacity: 0.78, depthWrite: false });
  for (const side of [-1, 1]) {
    const plate = new THREE.Mesh(new THREE.PlaneGeometry(0.62, 0.62), numberMat);
    plate.position.set(side * (dims.width / 2 + 0.075), 0.62, -dims.length * 0.04);
    plate.rotation.y = side > 0 ? Math.PI / 2 : -Math.PI / 2;
    bodyGroup.add(plate);
  }

  // Wheels
  const wheels = [];
  const wheelRadius = dims.wheel * build.chosen.wheels.radius;
  const rimMat = new THREE.MeshStandardMaterial({
    color: build.chosen.wheels.rim, emissive: build.chosen.wheels.rim, emissiveIntensity: 0.35,
    metalness: 0.9, roughness: 0.22,
  });
  const tireMat = new THREE.MeshStandardMaterial({ color: 0x070a0d, metalness: 0.1, roughness: 0.82 });
  for (const sx of [-1, 1]) {
    for (const sz of [-1, 1]) {
      const pivot = new THREE.Group();
      pivot.position.set(sx * (dims.width / 2 + 0.08), wheelRadius, sz * dims.wheelZ);
      const spinner = new THREE.Group();
      pivot.add(spinner);

      const tire = new THREE.Mesh(new THREE.CylinderGeometry(wheelRadius, wheelRadius, 0.34, 20, 1), tireMat);
      tire.rotation.z = Math.PI / 2;
      tire.castShadow = true;
      spinner.add(tire);

      const rim = new THREE.Mesh(new THREE.CylinderGeometry(wheelRadius * 0.64, wheelRadius * 0.64, 0.36, 16, 1), rimMat);
      rim.rotation.z = Math.PI / 2;
      spinner.add(rim);

      for (const side of [-1, 1]) {
        const ring = new THREE.Mesh(new THREE.TorusGeometry(wheelRadius * 0.68, 0.035, 6, 20), rimMat);
        ring.position.x = side * 0.18;
        ring.rotation.y = Math.PI / 2;
        spinner.add(ring);
      }
      // spokes
      for (let i = 0; i < 5; i += 1) {
        const spoke = new THREE.Mesh(new THREE.BoxGeometry(0.37, wheelRadius * 1.15, 0.035), darkMat);
        spoke.rotation.x = (i / 5) * Math.PI;
        spinner.add(spoke);
      }

      bodyGroup.add(pivot);
      wheels.push({ pivot, spinner, front: sz > 0 });
    }
  }

  // Thruster nozzles and flames
  const flameMats = [];
  const flames = [];
  const boostLights = [];
  for (const x of [-dims.width * 0.24, dims.width * 0.24]) {
    const nozzle = new THREE.Mesh(new THREE.CylinderGeometry(0.17, 0.22, 0.34, 12), darkMat);
    nozzle.rotation.x = Math.PI / 2;
    nozzle.position.set(x, 0.48, -dims.length / 2 - 0.02);
    bodyGroup.add(nozzle);
    const nozzleGlow = new THREE.Mesh(new THREE.CircleGeometry(0.13, 14), glowMat);
    nozzleGlow.position.set(x, 0.48, -dims.length / 2 - 0.2);
    nozzleGlow.rotation.y = Math.PI;
    bodyGroup.add(nozzleGlow);

    const flameMat = new THREE.MeshBasicMaterial({
      color: build.chosen.boost.flame, transparent: true, opacity: 0.9,
      blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide,
    });
    flameMats.push(flameMat);
    const flameCoreMat = new THREE.MeshBasicMaterial({
      color: build.chosen.boost.flame2, transparent: true, opacity: 0.9,
      blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide,
    });
    flameMats.push(flameCoreMat);
    const flame = new THREE.Mesh(new THREE.ConeGeometry(0.23, 2.2, 10, 1, true), flameMat);
    flame.rotation.x = -Math.PI / 2;
    flame.position.set(x, 0.48, -dims.length / 2 - 0.95);
    flame.visible = false;
    bodyGroup.add(flame);
    const core = new THREE.Mesh(new THREE.ConeGeometry(0.11, 1.4, 8, 1, true), flameCoreMat);
    core.rotation.x = -Math.PI / 2;
    core.position.set(x, 0.48, -dims.length / 2 - 0.72);
    core.visible = false;
    bodyGroup.add(core);
    flames.push({ flame, core });
    const light = new THREE.PointLight(new THREE.Color(build.chosen.boost.flame), 0, 9, 2);
    light.position.set(x, 0.55, -dims.length / 2 - 0.6);
    bodyGroup.add(light);
    boostLights.push(light);
  }

  // Topper
  const topperGroup = new THREE.Group();
  topperGroup.position.set(0, 0.68 + dims.cabin * 1.03, -dims.length * 0.04);
  bodyGroup.add(topperGroup);
  const topperId = build.chosen.topper.id;
  let topperSpin = null;
  if (topperId === 'halo') {
    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(0.52, 0.055, 8, 32),
      new THREE.MeshStandardMaterial({ color: 0xffe066, emissive: 0xffc933, emissiveIntensity: 3.2, metalness: 0.7, roughness: 0.2 }),
    );
    ring.rotation.x = Math.PI / 2;
    ring.position.y = 0.62;
    topperGroup.add(ring);
    for (let i = 0; i < 3; i += 1) {
      const a = (i / 3) * Math.PI * 2;
      const spoke = new THREE.Mesh(new THREE.BoxGeometry(0.035, 0.42, 0.035), darkMat);
      spoke.position.set(Math.cos(a) * 0.38, 0.4, Math.sin(a) * 0.38);
      spoke.rotation.z = Math.cos(a) * 0.25;
      spoke.rotation.x = Math.sin(a) * 0.25;
      topperGroup.add(spoke);
    }
    topperSpin = ring;
  } else if (topperId === 'mohawk') {
    for (let i = 0; i < 5; i += 1) {
      const fin = new THREE.Mesh(new THREE.ConeGeometry(0.16, 0.55 + (2 - Math.abs(i - 2)) * 0.15, 4), new THREE.MeshStandardMaterial({
        color: 0xff6a1a, emissive: 0xff4a00, emissiveIntensity: 2.5, metalness: 0.4, roughness: 0.35,
      }));
      fin.position.set(0, 0.3, (i - 2) * 0.22);
      fin.rotation.x = (i - 2) * 0.14;
      topperGroup.add(fin);
    }
  } else if (topperId === 'propeller') {
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.06, 0.5, 8), darkMat);
    pole.position.y = 0.25;
    topperGroup.add(pole);
    const rotor = new THREE.Group();
    rotor.position.y = 0.52;
    for (let i = 0; i < 3; i += 1) {
      const blade = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.03, 0.12), accentMat);
      blade.rotation.y = (i / 3) * Math.PI * 2;
      blade.geometry.translate(0.48, 0, 0);
      rotor.add(blade);
    }
    topperGroup.add(rotor);
    topperSpin = rotor;
  } else if (topperId === 'crown') {
    const band = new THREE.Mesh(new THREE.TorusGeometry(0.35, 0.07, 6, 20), new THREE.MeshStandardMaterial({
      color: 0xffc23d, emissive: 0xff9a00, emissiveIntensity: 2.4, metalness: 0.9, roughness: 0.2,
    }));
    band.rotation.x = Math.PI / 2;
    band.position.y = 0.2;
    topperGroup.add(band);
    for (let i = 0; i < 5; i += 1) {
      const a = (i / 5) * Math.PI * 2;
      const spike = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.42, 4), new THREE.MeshStandardMaterial({
        color: 0xffd25c, emissive: 0xffa000, emissiveIntensity: 2.2, metalness: 0.85, roughness: 0.2,
      }));
      spike.position.set(Math.cos(a) * 0.33, 0.35, Math.sin(a) * 0.33);
      topperGroup.add(spike);
    }
  } else if (topperId === 'satellite') {
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.05, 0.52, 6), darkMat);
    pole.position.y = 0.26;
    topperGroup.add(pole);
    const dish = new THREE.Mesh(new THREE.SphereGeometry(0.34, 16, 8, 0, Math.PI * 2, 0, Math.PI * 0.5), new THREE.MeshStandardMaterial({
      color: 0xbaffd4, emissive: 0x47ff9a, emissiveIntensity: 1.2, metalness: 0.5, roughness: 0.3, side: THREE.DoubleSide,
    }));
    dish.position.y = 0.58;
    dish.rotation.x = Math.PI * 0.8;
    topperGroup.add(dish);
    const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.012, 0.012, 0.3, 4), accentMat);
    antenna.position.set(0.2, 0.48, 0);
    topperGroup.add(antenna);
    topperSpin = dish;
  }

  // Indicator ring under car
  const indicatorMat = new THREE.MeshBasicMaterial({
    color: team.color, transparent: true, opacity: isPlayer ? 0.38 : 0.2,
    blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide,
  });
  const indicator = new THREE.Mesh(new THREE.RingGeometry(dims.width * 0.72, dims.width * 0.82, 40), indicatorMat);
  indicator.rotation.x = -Math.PI / 2;
  indicator.position.y = 0.035;
  group.add(indicator);

  // Underglow
  const under = new THREE.PointLight(team.color, 6, 7, 2);
  under.position.y = 0.35;
  group.add(under);

  return {
    group, bodyGroup, wheels, flames, flameMats, boostLights, topperSpin, indicator,
    dims, wheelRadius,
  };
}

export class Car {
  constructor(scene, { team, build, isPlayer = false, name = 'PLAYER', number = '07' }) {
    this.scene = scene;
    this.team = team;
    this.teamKey = team.key;
    this.build = build;
    this.isPlayer = isPlayer;
    this.name = name;
    this.number = number;
    this.pos = new THREE.Vector3();
    this.vel = new THREE.Vector3();
    this.yaw = 0;
    this.steer = 0;
    this.grounded = true;
    this.jumpCount = 0;
    this.boost = 33;
    this.boosting = false;
    this.hitCooldown = 0;
    this.visualRoll = 0;
    this.visualPitch = 0;
    this.wheelSpin = 0;
    this.flipTimer = 0;
    this.landTimer = 0;
    this.boostEmit = 0;
    this.topSpeed = 0;
    this.boostUsed = 0;
    this.hits = 0;
    this.stats = build.physics;
    this.visual = buildCarVisual(build, team, { isPlayer, number });
    this.scene.add(this.visual.group);
    this.visual.group.position.copy(this.pos);
  }

  setBuild(build) {
    const boostFrac = this.stats.capacity ? this.boost / this.stats.capacity : 0.33;
    const old = this.visual;
    this.scene.remove(old.group);
    disposeGroup(old.group);
    this.build = build;
    this.stats = build.physics;
    this.visual = buildCarVisual(build, this.team, { isPlayer: this.isPlayer, number: this.number });
    this.scene.add(this.visual.group);
    this.boost = boostFrac * this.stats.capacity;
    this.visual.group.position.copy(this.pos);
    this.visual.group.rotation.y = this.yaw;
  }

  reset(x, z, yaw, boost = 33) {
    this.pos.set(x, 0, z);
    this.vel.set(0, 0, 0);
    this.yaw = yaw;
    this.steer = 0;
    this.grounded = true;
    this.jumpCount = 0;
    this.boost = Math.min(boost, this.stats.capacity);
    this.boosting = false;
    this.hitCooldown = 0;
    this.visual.group.position.copy(this.pos);
    this.visual.group.rotation.y = yaw;
    this.visual.bodyGroup.rotation.set(0, 0, 0);
    this.visual.group.visible = true;
  }

  get forward() {
    return new THREE.Vector3(Math.sin(this.yaw), 0, Math.cos(this.yaw));
  }

  get right() {
    return new THREE.Vector3(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
  }

  get speed() {
    return Math.hypot(this.vel.x, this.vel.z);
  }

  addBoost(amount) {
    const before = this.boost;
    this.boost = Math.min(this.stats.capacity, this.boost + amount);
    return this.boost > before;
  }

  update(dt, input, ball, effects = {}) {
    const stats = this.stats;
    this.hitCooldown = Math.max(0, this.hitCooldown - dt);
    this.flipTimer = Math.max(0, this.flipTimer - dt);
    this.landTimer = Math.max(0, this.landTimer - dt);

    let forward = this.forward;
    let right = this.right;
    const fwdSpeed = this.vel.dot(forward);

    // Steering
    const dirSign = fwdSpeed < -0.8 ? -1 : 1;
    const speedFactor = this.grounded
      ? THREE.MathUtils.clamp(0.34 + Math.abs(fwdSpeed) / 9, 0.34, 1.08)
      : 0.55;
    const driftMul = input.drift && this.grounded ? 1.42 : 1;
    this.steer = damp(this.steer, input.steer, 14, dt);
    this.yaw += this.steer * stats.steerRate * speedFactor * driftMul * dirSign * dt;

    forward = this.forward;
    right = this.right;

    // Throttle
    let engineForce = 0;
    if (input.throttle > 0) {
      engineForce = stats.accel * input.throttle;
      if (fwdSpeed > stats.maxSpeed * 0.99) engineForce *= 0.15;
    } else if (input.throttle < 0) {
      if (fwdSpeed > 1.5) engineForce = -stats.accel * 1.35 * -input.throttle;
      else engineForce = stats.accel * 0.52 * input.throttle;
    }
    if (this.grounded) this.vel.addScaledVector(forward, engineForce * dt);
    else this.vel.addScaledVector(forward, engineForce * 0.28 * dt);

    // Boost
    const wantsBoost = !!input.boost && this.boost > 0.15;
    this.boosting = wantsBoost;
    if (wantsBoost) {
      const thrustAccel = 29 * stats.thrust;
      this.vel.addScaledVector(forward, thrustAccel * dt);
      if (!this.grounded) this.vel.y += 1.6 * dt;
      this.boost = Math.max(0, this.boost - stats.drain * dt);
      this.boostUsed += stats.drain * dt;
      this.boostEmit += dt;
      if (effects.boost) effects.boost(this, dt);
    } else if (stats.regen > 0) {
      this.boost = Math.min(stats.capacity, this.boost + stats.regen * dt);
    }

    // Grip and drag
    const lateral = this.vel.dot(right);
    const gripMul = this.grounded ? (input.drift ? 0.34 : 1) : 0.16;
    this.vel.addScaledVector(right, -lateral * Math.min(1, stats.grip * gripMul * dt));
    if (this.grounded) {
      const forwardDrag = input.throttle === 0 ? 0.85 : 0.16;
      const fwdComponent = this.vel.dot(forward);
      this.vel.addScaledVector(forward, -fwdComponent * Math.min(1, forwardDrag * dt));
    } else {
      this.vel.multiplyScalar(Math.exp(-0.08 * dt));
    }

    // Speed cap
    const flatSpeed = Math.hypot(this.vel.x, this.vel.z);
    const cap = stats.maxSpeed * (this.boosting ? 1.26 : 1.0);
    if (flatSpeed > cap) {
      const s = cap / flatSpeed;
      this.vel.x *= s;
      this.vel.z *= s;
    }

    // Jump / double jump
    if (input.jumpPressed) {
      if (this.grounded) {
        this.vel.y = stats.jumpSpeed;
        this.grounded = false;
        this.jumpCount = 1;
        this.landTimer = 0;
        if (effects.jump) effects.jump(this);
      } else if (this.jumpCount < 2) {
        this.vel.y = Math.max(this.vel.y, stats.jumpSpeed * 0.82);
        this.jumpCount = 2;
        const dir = new THREE.Vector3();
        dir.addScaledVector(forward, input.throttle);
        dir.addScaledVector(right, input.steer);
        if (dir.lengthSq() > 0.05) {
          dir.normalize();
          this.vel.addScaledVector(dir, 9.5 * (0.85 + stats.handling * 0.02));
          this.vel.y += 2.4;
        }
        this.flipTimer = 0.55;
        if (effects.flip) effects.flip(this);
      }
    }

    // Gravity
    if (!this.grounded) this.vel.y -= 37 * dt;

    // Integrate
    this.pos.addScaledVector(this.vel, dt);

    // Ground
    if (this.pos.y <= 0) {
      const impact = -this.vel.y;
      this.pos.y = 0;
      if (!this.grounded && impact > 3 && effects.land) effects.land(this, impact);
      this.vel.y = 0;
      this.grounded = true;
      this.jumpCount = 0;
    } else {
      this.grounded = false;
    }
    if (this.pos.y > FIELD.ceiling - 1.2) {
      this.pos.y = FIELD.ceiling - 1.2;
      this.vel.y = Math.min(0, this.vel.y);
    }

    // Arena walls (cars stay inside the pitch)
    const limitX = FIELD.halfX - 1.25;
    const limitZ = FIELD.halfZ - 1.1;
    if (this.pos.x > limitX) { this.pos.x = limitX; this.vel.x *= -0.28; this.vel.z *= 0.86; }
    if (this.pos.x < -limitX) { this.pos.x = -limitX; this.vel.x *= -0.28; this.vel.z *= 0.86; }
    if (this.pos.z > limitZ) { this.pos.z = limitZ; this.vel.z *= -0.28; this.vel.x *= 0.86; }
    if (this.pos.z < -limitZ) { this.pos.z = -limitZ; this.vel.z *= -0.28; this.vel.x *= 0.86; }

    // Ball collision
    if (ball) this.collideBall(ball, effects);

    this.topSpeed = Math.max(this.topSpeed, this.speed);
  }

  collideBall(ball, effects) {
    if (this.hitCooldown > 0 || ball.frozen) return;
    const dims = this.stats.dims;
    const center = new THREE.Vector3(this.pos.x, this.pos.y + 0.68, this.pos.z);
    const forward = this.forward;
    const right = this.right;
    const delta = new THREE.Vector3().subVectors(ball.pos, center);
    const localX = delta.dot(right);
    const localZ = delta.dot(forward);
    const halfX = dims.width * 0.47;
    const halfY = 0.5;
    const halfZ = dims.length * 0.46;
    const cx = THREE.MathUtils.clamp(localX, -halfX, halfX);
    const cy = THREE.MathUtils.clamp(delta.y, -halfY, halfY);
    const cz = THREE.MathUtils.clamp(localZ, -halfZ, halfZ);
    const closest = new THREE.Vector3()
      .copy(center)
      .addScaledVector(right, cx)
      .addScaledVector(UP, cy)
      .addScaledVector(forward, cz);
    const diff = new THREE.Vector3().subVectors(ball.pos, closest);
    let dist = diff.length();
    if (dist > ball.radius) return;

    let normal;
    if (dist < 0.0001) {
      normal = new THREE.Vector3(0, 1, 0);
      dist = 0.001;
    } else {
      normal = diff.divideScalar(dist);
    }
    const penetration = ball.radius - dist;
    ball.pos.addScaledVector(normal, penetration + 0.02);

    const rel = new THREE.Vector3().subVectors(ball.vel, this.vel);
    const closing = Math.max(0, -rel.dot(normal));
    const carIntoBall = Math.max(0, this.vel.dot(normal));
    const impact = Math.max(closing, carIntoBall);
    if (impact < 0.4 && penetration < 0.1) return;

    const boostBoost = this.boosting ? 1.14 : 1;
    const power = this.stats.hitPower * boostBoost;
    const kick = (2.4 + impact * 1.02) * power;
    ball.vel.addScaledVector(normal, kick * 0.55);
    ball.vel.addScaledVector(this.vel, 0.2 * power);
    ball.vel.y += Math.min(7.5, impact * 0.13) * power;

    // Nose punt
    const noseDistance = localZ - halfZ;
    if (localZ > halfZ * 0.55 && this.speed > 6) {
      ball.vel.addScaledVector(forward, this.speed * 0.26 * power);
    }
    if (noseDistance > 0 && normal.y < 0.6) {
      ball.vel.y += Math.min(3.4, this.speed * 0.06);
    }

    // Recoil
    this.vel.addScaledVector(normal, -impact * 0.035 / this.stats.weight);
    this.hitCooldown = 0.1;
    this.hits += 1;
    ball.lastTouch = this.teamKey;
    ball.lastTouchCar = this;
    ball.hitFlash = 1;
    if (effects.hit) effects.hit(this, ball, impact, normal);
  }

  updateVisual(dt, elapsed) {
    const v = this.visual;
    const fwdSpeed = this.vel.dot(this.forward);
    const lateral = this.vel.dot(this.right);
    v.group.position.copy(this.pos);

    const targetRoll = THREE.MathUtils.clamp(-this.steer * 0.1 - lateral * 0.006, -0.22, 0.22);
    const targetPitch = THREE.MathUtils.clamp((this.grounded ? 0 : -this.vel.dot(this.forward) * 0.0035) + (this.grounded ? 0 : this.vel.y * 0.002), -0.18, 0.18);
    this.visualRoll = damp(this.visualRoll, targetRoll, 9, dt);
    this.visualPitch = damp(this.visualPitch, targetPitch, 7, dt);
    v.bodyGroup.rotation.z = this.visualRoll;
    v.bodyGroup.rotation.x = this.visualPitch + (this.flipTimer > 0 ? Math.sin((0.55 - this.flipTimer) / 0.55 * Math.PI * 2) * 0.18 : 0);
    v.group.rotation.y = this.yaw;

    this.wheelSpin += (fwdSpeed * dt) / Math.max(0.3, v.wheelRadius);
    for (const wheel of v.wheels) {
      wheel.spinner.rotation.x = this.wheelSpin;
      if (wheel.front) wheel.pivot.rotation.y = this.steer * 0.42;
    }

    for (let i = 0; i < v.flames.length; i += 1) {
      const { flame, core } = v.flames[i];
      const on = this.boosting && this.boost > 0.1;
      flame.visible = on;
      core.visible = on;
      if (on) {
        const flicker = 0.82 + Math.sin(elapsed * 42 + i * 2.1) * 0.16 + Math.random() * 0.08;
        const length = 0.7 + Math.min(1.25, this.speed / 26) * 0.7;
        flame.scale.set(flicker, length, flicker);
        core.scale.set(1, length * 0.9, 1);
      }
      v.boostLights[i].intensity = on ? 9 + Math.random() * 4 : 0;
    }
    if (v.topperSpin) {
      if (this.build.chosen.topper.id === 'propeller') v.topperSpin.rotation.y += dt * (this.boosting ? 22 : 9);
      else if (this.build.chosen.topper.id === 'halo') v.topperSpin.rotation.z += dt * 0.8;
      else if (this.build.chosen.topper.id === 'satellite') v.topperSpin.rotation.y += dt * 0.5;
    }
    v.indicator.material.opacity = (this.isPlayer ? 0.32 : 0.16) + Math.sin(elapsed * 3) * 0.05;
  }

  dispose() {
    this.scene.remove(this.visual.group);
    disposeGroup(this.visual.group);
  }
}

import * as THREE from 'three';
import { FIELD } from './arena.js';

function makeBallTexture() {
  const canvas = document.createElement('canvas');
  canvas.width = 1024;
  canvas.height = 512;
  const ctx = canvas.getContext('2d');
  const grad = ctx.createLinearGradient(0, 0, 0, 512);
  grad.addColorStop(0, '#e8fbff');
  grad.addColorStop(0.5, '#c8e9f5');
  grad.addColorStop(1, '#a9d5e4');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, 1024, 512);

  // soccer-ball style dark panels on a distorted hex grid
  const cell = 86;
  for (let row = -1; row < 8; row += 1) {
    for (let col = -1; col < 14; col += 1) {
      const ox = (row % 2) * cell * 0.5;
      const cx = col * cell + ox;
      const cy = row * cell * 0.86;
      if ((row * 7 + col * 3) % 5 !== 0) continue;
      ctx.save();
      ctx.translate(cx, cy);
      ctx.rotate(((row * 13 + col * 7) % 10) * 0.06);
      ctx.beginPath();
      for (let i = 0; i < 6; i += 1) {
        const a = (i / 6) * Math.PI * 2 + Math.PI / 6;
        const px = Math.cos(a) * 31;
        const py = Math.sin(a) * 31;
        if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
      }
      ctx.closePath();
      ctx.fillStyle = '#132433';
      ctx.fill();
      ctx.strokeStyle = 'rgba(3, 10, 16, 0.85)';
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.restore();
    }
  }

  // Seams
  ctx.strokeStyle = 'rgba(20, 55, 70, 0.22)';
  ctx.lineWidth = 1.2;
  for (let i = 0; i < 26; i += 1) {
    ctx.beginPath();
    ctx.arc(Math.random() * 1024, Math.random() * 512, 30 + Math.random() * 55, 0, Math.PI * 2);
    ctx.stroke();
  }

  // Neon markings + brand
  ctx.save();
  ctx.globalAlpha = 0.7;
  ctx.fillStyle = '#2ee7ff';
  ctx.beginPath();
  ctx.arc(512, 256, 26, 0, Math.PI * 2);
  ctx.fill();
  ctx.globalAlpha = 0.28;
  ctx.lineWidth = 5;
  ctx.strokeStyle = '#2ee7ff';
  ctx.beginPath();
  ctx.arc(512, 256, 38, 0, Math.PI * 2);
  ctx.stroke();
  ctx.restore();
  ctx.save();
  ctx.globalAlpha = 0.4;
  ctx.fillStyle = '#0a2a3a';
  ctx.font = '900 34px Orbitron, sans-serif';
  ctx.textAlign = 'center';
  ctx.fillText('NEON', 512, 140);
  ctx.fillText('STRIKERS', 512, 390);
  ctx.restore();

  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  return tex;
}

function makeGlowSprite(color = 0xbfefff, size = 14) {
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  const g = ctx.createRadialGradient(64, 64, 0, 64, 64, 64);
  g.addColorStop(0, 'rgba(255,255,255,0.9)');
  g.addColorStop(0.18, 'rgba(180,240,255,0.55)');
  g.addColorStop(0.5, 'rgba(80,200,255,0.18)');
  g.addColorStop(1, 'rgba(40,160,255,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 128, 128);
  const tex = new THREE.CanvasTexture(canvas);
  tex.colorSpace = THREE.SRGBColorSpace;
  const mat = new THREE.SpriteMaterial({
    map: tex, color, transparent: true, opacity: 0.7, blending: THREE.AdditiveBlending,
    depthWrite: false,
  });
  const sprite = new THREE.Sprite(mat);
  sprite.scale.setScalar(size);
  return sprite;
}

export class Ball {
  constructor(scene) {
    this.scene = scene;
    this.radius = 2.2;
    this.pos = new THREE.Vector3(0, this.radius, 0);
    this.vel = new THREE.Vector3();
    this.frozen = false;
    this.lastTouch = null;
    this.lastTouchCar = null;
    this.hitFlash = 0;
    this.trailTimer = 0;

    const tex = makeBallTexture();
    this.material = new THREE.MeshStandardMaterial({
      map: tex,
      emissive: 0x1c4f63,
      emissiveMap: tex,
      emissiveIntensity: 0.75,
      metalness: 0.18,
      roughness: 0.44,
    });
    this.mesh = new THREE.Mesh(new THREE.SphereGeometry(this.radius, 48, 32), this.material);
    this.mesh.castShadow = true;
    this.mesh.receiveShadow = true;
    this.mesh.position.copy(this.pos);
    scene.add(this.mesh);

    this.shell = new THREE.Mesh(
      new THREE.SphereGeometry(this.radius * 1.015, 32, 20),
      new THREE.MeshBasicMaterial({
        color: 0x7fefff, wireframe: true, transparent: true, opacity: 0.095,
        blending: THREE.AdditiveBlending, depthWrite: false,
      }),
    );
    scene.add(this.shell);

    this.glow = makeGlowSprite(0xa8ecff, 15);
    scene.add(this.glow);

    this.light = new THREE.PointLight(0x9feaff, 12, 18, 2);
    scene.add(this.light);
  }

  reset() {
    this.pos.set(0, this.radius, 0);
    this.vel.set(0, 0, 0);
    this.frozen = false;
    this.hitFlash = 0;
    this.mesh.quaternion.identity();
    this.mesh.position.copy(this.pos);
    this.lastTouch = null;
    this.lastTouchCar = null;
  }

  update(dt, effects = {}) {
    if (this.frozen) {
      this.syncVisual(dt);
      return null;
    }
    const steps = 2;
    const h = dt / steps;
    let goal = null;
    for (let step = 0; step < steps && !goal; step += 1) {
      this.vel.y -= 31 * h;
      // air drag
      this.vel.multiplyScalar(Math.exp(-0.045 * h));
      this.pos.addScaledVector(this.vel, h);
      goal = this.resolveCollisions(effects);
    }
    if (goal) {
      this.frozen = true;
    }
    this.syncVisual(dt);
    return goal;
  }

  resolveCollisions(effects) {
    const r = this.radius;
    const halfX = FIELD.halfX;
    const halfZ = FIELD.halfZ;
    let goal = null;

    // Floor
    if (this.pos.y < r) {
      this.pos.y = r;
      if (this.vel.y < 0) {
        const impact = -this.vel.y;
        this.vel.y = impact > 1.2 ? impact * 0.7 : 0;
        this.vel.x *= 0.992;
        this.vel.z *= 0.992;
        if (impact > 9 && effects.bounce) effects.bounce(this, impact);
      }
    }
    // Ceiling
    if (this.pos.y > FIELD.ceiling - r) {
      this.pos.y = FIELD.ceiling - r;
      if (this.vel.y > 0) this.vel.y *= -0.62;
    }
    // Side walls
    if (this.pos.z > halfZ - r) {
      this.pos.z = halfZ - r;
      if (this.vel.z > 0) this.vel.z *= -0.68;
      this.vel.x *= 0.985;
      if (effects.wallBounce) effects.wallBounce(this);
    } else if (this.pos.z < -halfZ + r) {
      this.pos.z = -halfZ + r;
      if (this.vel.z < 0) this.vel.z *= -0.68;
      this.vel.x *= 0.985;
      if (effects.wallBounce) effects.wallBounce(this);
    }

    const inMouthZ = Math.abs(this.pos.z) < FIELD.goalHalfZ - 0.15;
    const inMouthY = this.pos.y < FIELD.goalHeight - 0.2;

    // End walls / goals
    for (const side of [-1, 1]) {
      const backX = side * (halfX + FIELD.goalDepth);
      if (side > 0) {
        if (this.pos.x > halfX - r) {
          if (!(inMouthZ && inMouthY)) {
            this.pos.x = halfX - r;
            if (this.vel.x > 0) this.vel.x *= -0.7;
            this.vel.y *= 0.97;
            this.vel.z *= 0.985;
            if (effects.wallBounce) effects.wallBounce(this);
          } else {
            // Goal interior
            if (this.pos.x > backX - r + 0.5) {
              this.pos.x = backX - r + 0.5;
              if (this.vel.x > 0) this.vel.x *= -0.4;
            }
            if (Math.abs(this.pos.z) > FIELD.goalHalfZ - r + 0.5) {
              this.pos.z = Math.sign(this.pos.z) * (FIELD.goalHalfZ - r + 0.5);
              this.vel.z *= -0.4;
            }
            if (this.pos.y > FIELD.goalHeight - r + 0.4) {
              this.pos.y = FIELD.goalHeight - r + 0.4;
              this.vel.y *= -0.4;
            }
            if (this.pos.x > halfX + 1.4) goal = 'blue';
          }
        }
      } else if (this.pos.x < -halfX + r) {
        if (!(inMouthZ && inMouthY)) {
          this.pos.x = -halfX + r;
          if (this.vel.x < 0) this.vel.x *= -0.7;
          this.vel.y *= 0.97;
          this.vel.z *= 0.985;
          if (effects.wallBounce) effects.wallBounce(this);
        } else {
          if (this.pos.x < backX + r - 0.5) {
            this.pos.x = backX + r - 0.5;
            if (this.vel.x < 0) this.vel.x *= -0.4;
          }
          if (Math.abs(this.pos.z) > FIELD.goalHalfZ - r + 0.5) {
            this.pos.z = Math.sign(this.pos.z) * (FIELD.goalHalfZ - r + 0.5);
            this.vel.z *= -0.4;
          }
          if (this.pos.y > FIELD.goalHeight - r + 0.4) {
            this.pos.y = FIELD.goalHeight - r + 0.4;
            this.vel.y *= -0.4;
          }
          if (this.pos.x < -halfX - 1.4) goal = 'orange';
        }
      }
    }

    // Goal posts (simple cylinder caps)
    for (const side of [-1, 1]) {
      for (const z of [-FIELD.goalHalfZ, FIELD.goalHalfZ]) {
        const dx = this.pos.x - side * halfX;
        const dy = this.pos.y - FIELD.goalHeight / 2;
        const dz = this.pos.z - z;
        const d = Math.sqrt(dx * dx + dz * dz);
        const minDist = r + 0.38;
        if (Math.abs(dy) < FIELD.goalHeight / 2 + 0.2 && d < minDist && d > 0.001) {
          const nx = dx / d;
          const nz = dz / d;
          this.pos.x = side * halfX + nx * minDist;
          this.pos.z = z + nz * minDist;
          const vn = this.vel.x * nx + this.vel.z * nz;
          if (vn < 0) {
            this.vel.x -= 1.5 * vn * nx;
            this.vel.z -= 1.5 * vn * nz;
          }
        }
      }
    }
    return goal;
  }

  syncVisual(dt) {
    this.mesh.position.copy(this.pos);
    this.shell.position.copy(this.pos);
    this.glow.position.copy(this.pos);
    this.light.position.copy(this.pos);
    const speed = this.vel.length();
    this.glow.scale.setScalar(14 + Math.min(10, speed * 0.22));
    this.glow.material.opacity = 0.35 + Math.min(0.4, speed * 0.008);
    this.light.intensity = 8 + Math.min(22, speed * 0.45);
    this.hitFlash = Math.max(0, this.hitFlash - dt * 2.8);
    this.material.emissiveIntensity = 0.7 + this.hitFlash * 2.8;
    if (speed > 0.2) {
      const axis = new THREE.Vector3(-this.vel.z, 0, this.vel.x).normalize();
      const angle = (speed * dt) / this.radius;
      this.mesh.rotateOnWorldAxis(axis, angle);
      this.shell.rotateOnWorldAxis(axis, angle * 0.6);
    }
    this.shell.material.opacity = 0.07 + Math.min(0.15, speed * 0.0025) + this.hitFlash * 0.12;
  }
}

import * as THREE from 'three';

const PARTICLE_VERT = `
  attribute float size;
  attribute float alpha;
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vColor = color;
    vAlpha = alpha;
    vec4 mv = modelViewMatrix * vec4(position, 1.0);
    gl_PointSize = size * (330.0 / max(1.0, -mv.z));
    gl_Position = projectionMatrix * mv;
  }
`;
const PARTICLE_FRAG = `
  varying vec3 vColor;
  varying float vAlpha;
  void main() {
    vec2 p = gl_PointCoord - 0.5;
    float d = length(p);
    if (d > 0.5) discard;
    float glow = smoothstep(0.5, 0.05, d);
    gl_FragColor = vec4(vColor, glow * vAlpha);
  }
`;

export class FX {
  constructor(scene) {
    this.scene = scene;
    this.max = 1400;
    this.cursor = 0;
    this.particles = [];
    const positions = new Float32Array(this.max * 3);
    const colors = new Float32Array(this.max * 3);
    const sizes = new Float32Array(this.max);
    const alphas = new Float32Array(this.max);
    this.geometry = new THREE.BufferGeometry();
    this.geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    this.geometry.setAttribute('color', new THREE.BufferAttribute(colors, 3));
    this.geometry.setAttribute('size', new THREE.BufferAttribute(sizes, 1));
    this.geometry.setAttribute('alpha', new THREE.BufferAttribute(alphas, 1));
    this.material = new THREE.ShaderMaterial({
      uniforms: {},
      vertexShader: PARTICLE_VERT,
      fragmentShader: PARTICLE_FRAG,
      vertexColors: true,
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
    });
    this.points = new THREE.Points(this.geometry, this.material);
    this.points.frustumCulled = false;
    scene.add(this.points);
    this.rings = [];
    this.ringGeometry = new THREE.RingGeometry(0.92, 1.0, 72);
    this.tmpColor = new THREE.Color();
    this.emitAccum = 0;
  }

  spawn(opts) {
    const {
      position, count = 1, spread = 0.2, speed = 0, speedSpread = 0,
      direction = null, colors = [0xffffff], size = [0.3, 0.9], life = [0.4, 1.0],
      gravity = 0, drag = 0.2, upward = 0,
    } = opts;
    for (let i = 0; i < count; i += 1) {
      const idx = this.cursor;
      this.cursor = (this.cursor + 1) % this.max;
      const p = this.particles[idx] || { pos: new THREE.Vector3(), vel: new THREE.Vector3(), color: new THREE.Color() };
      p.pos.copy(position);
      p.pos.x += (Math.random() - 0.5) * spread;
      p.pos.y += (Math.random() - 0.5) * spread;
      p.pos.z += (Math.random() - 0.5) * spread;
      p.vel.set(0, 0, 0);
      if (direction) p.vel.copy(direction).multiplyScalar(speed + Math.random() * speedSpread);
      else {
        p.vel.set(Math.random() - 0.5, Math.random() - 0.5, Math.random() - 0.5)
          .normalize().multiplyScalar(speed + Math.random() * speedSpread);
      }
      p.vel.y += upward * (0.5 + Math.random());
      p.vel.x += (Math.random() - 0.5) * speedSpread * 0.45;
      p.vel.z += (Math.random() - 0.5) * speedSpread * 0.45;
      const base = colors[Math.floor(Math.random() * colors.length)];
      p.color.set(base);
      if (Math.random() < 0.25) p.color.lerp(new THREE.Color(0xffffff), 0.6);
      p.size = size[0] + Math.random() * (size[1] - size[0]);
      p.maxLife = life[0] + Math.random() * (life[1] - life[0]);
      p.life = p.maxLife;
      p.gravity = gravity;
      p.drag = drag;
      p.active = true;
      this.particles[idx] = p;
    }
  }

  ring(position, color, plane = 'x', duration = 0.7, maxScale = 24) {
    const mat = new THREE.MeshBasicMaterial({
      color, transparent: true, opacity: 0.8, side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending, depthWrite: false,
    });
    const mesh = new THREE.Mesh(this.ringGeometry, mat);
    mesh.position.copy(position);
    if (plane === 'x') mesh.rotation.y = Math.PI / 2;
    else if (plane === 'floor') mesh.rotation.x = -Math.PI / 2;
    mesh.scale.setScalar(1);
    this.scene.add(mesh);
    this.rings.push({ mesh, time: 0, duration, maxScale });
  }

  boost(car, dt) {
    this.emitAccum += dt * 55;
    const emit = Math.floor(this.emitAccum);
    if (emit <= 0) return;
    this.emitAccum -= emit;
    const fwd = car.forward;
    const pos = new THREE.Vector3().copy(car.pos)
      .addScaledVector(fwd, -car.stats.dims.length * 0.5)
      .add(new THREE.Vector3(0, 0.5, 0));
    const dir = new THREE.Vector3().copy(fwd).multiplyScalar(-1);
    const colors = [car.build.chosen.boost.flame, car.build.chosen.boost.flame2, 0xffffff];
    this.spawn({
      position: pos, count: emit, spread: 0.26, direction: dir, speed: 6, speedSpread: 5,
      colors, size: [0.25, 0.65], life: [0.16, 0.4], gravity: -1.5, drag: 1.6,
    });
  }

  hit(car, ball, impact, normal) {
    const count = Math.min(34, Math.floor(8 + impact * 0.7));
    const pos = ball.pos.clone().addScaledVector(normal, -ball.radius * 0.45);
    const teamColor = car.team.bright;
    const colors = [teamColor, 0xffffff, 0xffe6a8];
    this.spawn({
      position: pos, count, spread: ball.radius * 0.65, direction: normal, speed: 5,
      speedSpread: impact * 0.65, colors, size: [0.3, 1.0], life: [0.25, 0.8], gravity: 4, drag: 1.0,
    });
    this.ring(pos, teamColor, 'x', 0.32, 4 + impact * 0.2);
  }

  land(car, impact) {
    const pos = new THREE.Vector3(car.pos.x, 0.12, car.pos.z);
    this.spawn({
      position: pos, count: Math.min(15, Math.floor(impact)), spread: 1.2, speed: 2.5,
      speedSpread: 4, colors: [0x9fd5e8, 0x4a7c92, 0xffffff], size: [0.2, 0.7],
      life: [0.25, 0.65], gravity: 1, drag: 2.2, upward: 0.3,
    });
  }

  jump(car) {
    const pos = new THREE.Vector3(car.pos.x, 0.15, car.pos.z);
    this.spawn({
      position: pos, count: 8, spread: 1.4, speed: 3, speedSpread: 2.5,
      colors: [car.team.bright, 0xffffff], size: [0.18, 0.5], life: [0.2, 0.45], gravity: 2, drag: 2,
    });
  }

  flip(car) {
    this.spawn({
      position: new THREE.Vector3(car.pos.x, car.pos.y + 0.7, car.pos.z),
      count: 14, spread: 1.4, speed: 4, speedSpread: 4,
      colors: [car.team.bright, 0xffffff], size: [0.25, 0.7], life: [0.2, 0.5], gravity: 2, drag: 1.5,
    });
  }

  bounce(ball, impact) {
    this.spawn({
      position: ball.pos.clone(), count: Math.min(16, Math.floor(impact * 0.9)),
      spread: ball.radius * 1.4, speed: 2, speedSpread: impact * 0.3,
      colors: [0x9feaff, 0xffffff], size: [0.2, 0.6], life: [0.2, 0.55], gravity: 3, drag: 1.4,
    });
  }

  wallBounce(ball) {
    this.spawn({
      position: ball.pos.clone(), count: 7, spread: 1.2, speed: 2, speedSpread: 3,
      colors: [0x7fd7ff, 0xffffff], size: [0.18, 0.5], life: [0.15, 0.4], gravity: 1, drag: 2,
    });
  }

  trail(ball) {
    const speed = ball.vel.length();
    if (speed < 13) return;
    this.spawn({
      position: ball.pos.clone(), count: speed > 34 ? 2 : 1, spread: ball.radius * 0.8,
      speed: 0.4, speedSpread: 1.2, colors: [0x7fe6ff, 0xffffff, 0x2ee7ff],
      size: [0.25, 0.85], life: [0.2, 0.55], gravity: 0, drag: 1.8,
    });
  }

  goal(position, team, color) {
    const main = new THREE.Color(color);
    const colors = [color, 0xffffff, 0xffd28a, team === 'blue' ? 0x2d83ff : 0xff6a12];
    this.spawn({
      position, count: 260, spread: 3.5, speed: 12, speedSpread: 26,
      colors, size: [0.45, 1.7], life: [0.7, 2.0], gravity: 7, drag: 0.55, upward: 1.2,
    });
    this.spawn({
      position, count: 120, spread: 5.5, speed: 5, speedSpread: 22,
      colors: [0xffffff, main.getHex()], size: [0.8, 2.8], life: [0.3, 1.1], gravity: 2, drag: 1.2,
    });
    this.ring(position, color, 'x', 0.9, 34);
    this.ring(position, 0xffffff, 'x', 0.65, 22);
    this.ring(new THREE.Vector3(position.x, 0.08, position.z), color, 'floor', 1.2, 30);
  }

  update(dt) {
    const positions = this.geometry.attributes.position.array;
    const colors = this.geometry.attributes.color.array;
    const sizes = this.geometry.attributes.size.array;
    const alphas = this.geometry.attributes.alpha.array;
    for (let i = 0; i < this.max; i += 1) {
      const p = this.particles[i];
      if (!p || !p.active) {
        alphas[i] = 0;
        sizes[i] = 0;
        continue;
      }
      p.life -= dt;
      if (p.life <= 0) {
        p.active = false;
        alphas[i] = 0;
        sizes[i] = 0;
        continue;
      }
      p.vel.y -= p.gravity * dt;
      p.vel.multiplyScalar(Math.exp(-p.drag * dt));
      p.pos.addScaledVector(p.vel, dt);
      if (p.pos.y < 0.05) { p.pos.y = 0.05; p.vel.y *= -0.35; }
      positions[i * 3] = p.pos.x;
      positions[i * 3 + 1] = p.pos.y;
      positions[i * 3 + 2] = p.pos.z;
      colors[i * 3] = p.color.r;
      colors[i * 3 + 1] = p.color.g;
      colors[i * 3 + 2] = p.color.b;
      sizes[i] = p.size * (0.6 + 0.4 * (p.life / p.maxLife));
      alphas[i] = Math.min(1, (p.life / p.maxLife) * 1.8) * 0.85;
    }
    this.geometry.attributes.position.needsUpdate = true;
    this.geometry.attributes.color.needsUpdate = true;
    this.geometry.attributes.size.needsUpdate = true;
    this.geometry.attributes.alpha.needsUpdate = true;

    for (let i = this.rings.length - 1; i >= 0; i -= 1) {
      const ring = this.rings[i];
      ring.time += dt;
      const t = Math.min(1, ring.time / ring.duration);
      const s = 1 + (ring.maxScale - 1) * (1 - Math.pow(1 - t, 3));
      ring.mesh.scale.setScalar(s);
      ring.mesh.material.opacity = 0.8 * (1 - t) * (1 - t);
      if (t >= 1) {
        this.scene.remove(ring.mesh);
        ring.mesh.material.dispose();
        this.rings.splice(i, 1);
      }
    }
  }
}

export class GameAudio {
  constructor() {
    this.ctx = null;
    this.ready = false;
    this.muted = false;
    try { this.muted = localStorage.getItem('neon-strikers-muted') === '1'; } catch { /* ignore */ }
    this.engineOn = false;
    this.lastBoost = false;
  }

  init() {
    if (this.ready) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    this.ctx = ctx;
    this.master = ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.82;
    this.compressor = ctx.createDynamicsCompressor();
    this.compressor.threshold.value = -18;
    this.compressor.knee.value = 18;
    this.compressor.ratio.value = 5;
    this.compressor.attack.value = 0.005;
    this.compressor.release.value = 0.22;
    this.master.connect(this.compressor);
    this.compressor.connect(ctx.destination);

    this.noiseBuffer = this.makeNoise(2.2);

    // Engine
    this.engineGain = ctx.createGain();
    this.engineGain.gain.value = 0;
    this.engineFilter = ctx.createBiquadFilter();
    this.engineFilter.type = 'lowpass';
    this.engineFilter.frequency.value = 330;
    this.engineFilter.Q.value = 4;
    this.engineGain.connect(this.engineFilter);
    this.engineFilter.connect(this.master);

    this.engineOsc1 = ctx.createOscillator();
    this.engineOsc1.type = 'sawtooth';
    this.engineOsc1.frequency.value = 48;
    this.engineOsc2 = ctx.createOscillator();
    this.engineOsc2.type = 'square';
    this.engineOsc2.frequency.value = 24;
    const o2gain = ctx.createGain();
    o2gain.gain.value = 0.35;
    this.engineOsc1.connect(this.engineGain);
    this.engineOsc2.connect(o2gain);
    o2gain.connect(this.engineGain);
    this.engineOsc1.start();
    this.engineOsc2.start();

    // Boost noise
    this.boostGain = ctx.createGain();
    this.boostGain.gain.value = 0;
    this.boostFilter = ctx.createBiquadFilter();
    this.boostFilter.type = 'bandpass';
    this.boostFilter.frequency.value = 1100;
    this.boostFilter.Q.value = 0.8;
    const boostSrc = ctx.createBufferSource();
    boostSrc.buffer = this.noiseBuffer;
    boostSrc.loop = true;
    boostSrc.connect(this.boostFilter);
    this.boostFilter.connect(this.boostGain);
    this.boostGain.connect(this.master);
    boostSrc.start();

    this.ready = true;
  }

  makeNoise(seconds) {
    const ctx = this.ctx;
    const buffer = ctx.createBuffer(1, Math.floor(ctx.sampleRate * seconds), ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i += 1) data[i] = Math.random() * 2 - 1;
    return buffer;
  }

  setMuted(muted) {
    this.muted = muted;
    try { localStorage.setItem('neon-strikers-muted', muted ? '1' : '0'); } catch { /* ignore */ }
    if (this.master && this.ctx) {
      this.master.gain.cancelScheduledValues(this.ctx.currentTime);
      this.master.gain.setTargetAtTime(muted ? 0 : 0.82, this.ctx.currentTime, 0.05);
    }
  }

  toggleMuted() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  setEngine(speed, boosting, active = true) {
    if (!this.ready) return;
    const t = this.ctx.currentTime;
    this.engineGain.gain.setTargetAtTime(active ? 0.026 + Math.min(0.035, speed * 0.0012) : 0, t, 0.08);
    this.engineOsc1.frequency.setTargetAtTime(42 + Math.min(80, speed * 2.1) + (boosting ? 16 : 0), t, 0.06);
    this.engineOsc2.frequency.setTargetAtTime(21 + Math.min(40, speed * 1.05), t, 0.06);
    this.engineFilter.frequency.setTargetAtTime(280 + Math.min(900, speed * 22) + (boosting ? 500 : 0), t, 0.08);
    this.boostGain.gain.setTargetAtTime(boosting && active ? 0.09 : 0, t, 0.05);
    this.boostFilter.frequency.setTargetAtTime(900 + Math.min(900, speed * 16), t, 0.1);
    this.lastBoost = boosting;
  }

  noiseBurst({ duration = 0.18, volume = 0.2, freq = 700, q = 1.2, type = 'bandpass', decay = 0.15 }) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const filter = ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    filter.Q.value = q;
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(volume, t);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + decay);
    src.connect(filter);
    filter.connect(gain);
    gain.connect(this.master);
    src.start(t);
    src.stop(t + duration + 0.05);
  }

  tone({ freq = 440, endFreq = null, duration = 0.2, volume = 0.1, type = 'sine', delay = 0, attack = 0.005 }) {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (endFreq) osc.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + duration);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(volume, t + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);
    osc.connect(gain);
    gain.connect(this.master);
    osc.start(t);
    osc.stop(t + duration + 0.05);
  }

  hit(power = 1) {
    if (!this.ready) return;
    const v = Math.min(0.5, 0.1 + power * 0.014);
    this.noiseBurst({ volume: v, freq: 560, q: 0.9, decay: 0.16, duration: 0.2 });
    this.tone({ freq: 120, endFreq: 42, duration: 0.18, volume: v * 0.9, type: 'sine' });
  }

  bounce(power = 1) {
    this.tone({ freq: 90, endFreq: 48, duration: 0.15, volume: Math.min(0.2, 0.03 + power * 0.004), type: 'triangle' });
    this.noiseBurst({ volume: 0.04, freq: 320, decay: 0.08, duration: 0.12 });
  }

  jump() {
    this.tone({ freq: 180, endFreq: 420, duration: 0.16, volume: 0.06, type: 'triangle' });
    this.noiseBurst({ volume: 0.035, freq: 1400, decay: 0.07, duration: 0.1 });
  }

  flip() {
    this.tone({ freq: 280, endFreq: 620, duration: 0.2, volume: 0.055, type: 'sawtooth' });
  }

  land(power = 1) {
    this.tone({ freq: 75, endFreq: 38, duration: 0.16, volume: Math.min(0.16, 0.04 + power * 0.003), type: 'sine' });
  }

  pad(big = false) {
    this.tone({ freq: big ? 340 : 520, endFreq: big ? 760 : 880, duration: 0.18, volume: big ? 0.075 : 0.045, type: 'sine' });
    if (big) this.tone({ freq: 170, endFreq: 340, duration: 0.2, volume: 0.05, type: 'triangle' });
  }

  beep(high = false) {
    this.tone({ freq: high ? 880 : 520, duration: high ? 0.5 : 0.18, volume: high ? 0.11 : 0.08, type: 'square' });
  }

  goal(team = 'blue') {
    if (!this.ready) return;
    const ctx = this.ctx;
    const t = ctx.currentTime;
    const base = team === 'blue' ? 220 : 196;
    [1, 1.25, 1.5, 2].forEach((ratio, i) => {
      this.tone({ freq: base * ratio, endFreq: base * ratio * 2, duration: 1.5, volume: 0.055, type: 'sawtooth', delay: i * 0.06 });
    });
    this.tone({ freq: 70, endFreq: 32, duration: 0.9, volume: 0.18, type: 'sine' });
    this.noiseBurst({ volume: 0.2, freq: 900, q: 0.5, decay: 0.9, duration: 1.1 });
    this.noiseBurst({ volume: 0.14, freq: 2600, q: 0.7, decay: 0.5, duration: 0.7 });
  }

  countdown(final = false) {
    if (final) {
      this.tone({ freq: 660, endFreq: 1320, duration: 0.55, volume: 0.12, type: 'square' });
      this.tone({ freq: 330, endFreq: 660, duration: 0.55, volume: 0.1, type: 'sawtooth' });
    } else {
      this.tone({ freq: 440, duration: 0.16, volume: 0.08, type: 'square' });
    }
  }

  whistle() {
    this.tone({ freq: 1200, endFreq: 1500, duration: 0.22, volume: 0.07, type: 'sine' });
    this.tone({ freq: 1180, endFreq: 1480, duration: 0.22, volume: 0.06, type: 'sine', delay: 0.04 });
  }

  ui() {
    this.tone({ freq: 720, endFreq: 980, duration: 0.08, volume: 0.035, type: 'triangle' });
  }

  select() {
    this.tone({ freq: 460, endFreq: 620, duration: 0.09, volume: 0.04, type: 'square' });
  }

  win() {
    [0, 0.12, 0.26, 0.42].forEach((delay, i) => {
      this.tone({ freq: [392, 523, 659, 784][i], duration: 0.5, volume: 0.08, type: 'triangle', delay });
    });
  }

  lose() {
    [0, 0.15, 0.32].forEach((delay, i) => {
      this.tone({ freq: [330, 262, 196][i], duration: 0.55, volume: 0.07, type: 'triangle', delay });
    });
  }
}

